/* DAWAH X — ahmad, অধ্যায় 89 · খণ্ড 89 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][89]=[[17601,17601,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏ثَرْوَانَ بْنِ مِلْحَانَ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا فِي الْمَسْجِدِ فَمَرَّ عَلَيْنَا ‏ ‏عَمَّارُ بْنُ يَاسِرٍ ‏ ‏فَقُلْنَا لَهُ حَدِّثْنَا مَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي الْفِتْنَةِ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَكُونُ بَعْدِي قَوْمٌ يَأْخُذُونَ الْمُلْكَ يَقْتُلُ عَلَيْهِ بَعْضُهُمْ بَعْضًا ‏ ‏قَالَ ‏ ‏قُلْنَا لَهُ لَوْ حَدَّثَنَا غَيْرُكَ مَا صَدَّقْنَاهُ ‏ ‏قَالَ ‏ ‏فَإِنَّهُ سَيَكُونُ ‏","","",""],[17602,17602,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ مُحَمَّدِ بْنِ خُثَيْمٍ الْمُحَارِبِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ خُثَيْمٍ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ يَاسِرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَنَا ‏ ‏وَعَلِيٌّ ‏ ‏رَفِيقَيْنِ فِي غَزْوَةِ ‏ ‏ذَاتِ الْعُشَيْرَةِ ‏ ‏فَلَمَّا نَزَلَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَقَامَ بِهَا رَأَيْنَا أُنَاسًا مِنْ ‏ ‏بَنِي مُدْلِجٍ ‏ ‏يَعْمَلُونَ فِي عَيْنٍ لَهُمْ فِي نَخْلٍ فَقَالَ لِي ‏ ‏عَلِيٌّ ‏ ‏يَا ‏ ‏أَبَا الْيَقْظَانِ ‏ ‏هَلْ لَكَ أَنْ تَأْتِيَ هَؤُلَاءِ فَنَنْظُرَ كَيْفَ يَعْمَلُونَ فَجِئْنَاهُمْ فَنَظَرْنَا إِلَى عَمَلِهِمْ سَاعَةً ثُمَّ غَشِيَنَا النَّوْمُ فَانْطَلَقْتُ أَنَا ‏ ‏وَعَلِيٌّ ‏ ‏فَاضْطَجَعْنَا فِي صَوْرٍ مِنْ النَّخْلِ فِي ‏ ‏دَقْعَاءَ ‏ ‏مِنْ التُّرَابِ فَنِمْنَا فَوَاللَّهِ مَا أَهَبَّنَا إِلَّا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَرِّكُنَا بِرِجْلِهِ وَقَدْ تَتَرَّبْنَا مِنْ تِلْكَ ‏ ‏الدَّقْعَاءِ ‏ ‏فَيَوْمَئِذٍ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِعَلِيٍّ ‏ ‏يَا أَبَا تُرَابٍ لِمَا يُرَى عَلَيْهِ مِنْ التُّرَابِ قَالَ ‏ ‏أَلَا أُحَدِّثُكُمَا بِأَشْقَى النَّاسِ رَجُلَيْنِ قُلْنَا بَلَى يَا رَسُولَ اللَّهِ قَالَ ‏ ‏أُحَيْمِرُ ‏ ‏ثَمُودَ ‏ ‏الَّذِي عَقَرَ النَّاقَةَ وَالَّذِي يَضْرِبُكَ يَا ‏ ‏عَلِيُّ ‏ ‏عَلَى هَذِهِ ‏ ‏يَعْنِي قَرْنَهُ ‏ ‏حَتَّى تُبَلَّ مِنْهُ هَذِهِ ‏ ‏يَعْنِي لِحْيَتَهُ ‏","","",""],[17603,17603,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ يَاسِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَرَّسَ ‏ ‏بِأُوَلَاتِ الْجَيْشِ وَمَعَهُ ‏ ‏عَائِشَةُ ‏ ‏زَوْجَتُهُ فَانْقَطَعَ عِقْدٌ لَهَا مِنْ ‏ ‏جَزْعِ ‏ ‏ظَفَارِ ‏ ‏فَحُبِسَ النَّاسُ ‏ ‏ابْتِغَاءَ ‏ ‏عِقْدِهَا وَذَلِكَ حَتَّى أَضَاءَ الْفَجْرُ وَلَيْسَ مَعَ النَّاسِ مَاءٌ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ عَلَى رَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُخْصَةَ التَّطَهُّرِ ‏ ‏بِالصَّعِيدِ ‏ ‏الطَّيِّبِ فَقَامَ الْمُسْلِمُونَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَضَرَبُوا بِأَيْدِيهِمْ الْأَرْضَ ثُمَّ رَفَعُوا أَيْدِيَهُمْ وَلَمْ يَقْبِضُوا مِنْ التُّرَابِ شَيْئًا فَمَسَحُوا بِهَا وُجُوهَهُمْ وَأَيْدِيَهُمْ إِلَى ‏ ‏الْمَنَاكِبِ ‏ ‏وَمِنْ بُطُونِ أَيْدِيهِمْ إِلَى الْآبَاطِ وَلَا يَغْتَرُّ بِهَذَا النَّاسُ ‏ ‏وَبَلَغَنَا أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏قَالَ ‏ ‏لِعَائِشَةَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏وَاللَّهِ مَا عَلِمْتُ إِنَّكِ لَمُبَارَكَةٌ ‏","","",""],[17604,17604,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْحَكَمِ بْنِ ثَوْبَانَ ‏ ‏عَنِ ‏ ‏ابْنِ لَاسٍ الْخُزَاعِيِّ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏عَمَّارُ بْنُ يَاسِرٍ ‏ ‏الْمَسْجِدَ فَرَكَعَ فِيهِ رَكْعَتَيْنِ أَخَفَّهُمَا وَأَتَمَّهُمَا قَالَ ثُمَّ جَلَسَ فَقُمْنَا إِلَيْهِ فَجَلَسْنَا عِنْدَهُ ثُمَّ قُلْنَا لَهُ لَقَدْ خَفَّفْتَ رَكْعَتَيْكَ هَاتَيْنِ جِدًّا يَا ‏ ‏أَبَا الْيَقْظَانِ ‏ ‏فَقَالَ إِنِّي بَادَرْتُ بِهِمَا الشَّيْطَانَ أَنْ يَدْخُلَ عَلَيَّ فِيهِمَا ‏ ‏قَالَ فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏قَالَ ‏ ‏صَلَّى ‏ ‏عَمَّارٌ ‏ ‏صَلَاةً فَجَوَّزَ فِيهَا فَسُئِلَ ‏ ‏أَوْ فَقِيلَ لَهُ ‏ ‏فَقَالَ ‏ ‏مَا ‏ ‏خَرَمْتُ ‏ ‏مِنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[17605,17605,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ الْأَزْرَقُ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا ‏ ‏عَمَّارٌ ‏ ‏صَلَاةً فَأَوْجَزَ فِيهَا فَأَنْكَرُوا ذَلِكَ فَقَالَ أَلَمْ أُتِمَّ الرُّكُوعَ وَالسُّجُودَ قَالُوا بَلَى قَالَ أَمَا إِنِّي قَدْ دَعَوْتُ فِيهِمَا بِدُعَاءٍ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْعُو بِهِ ‏ ‏اللَّهُمَّ بِعِلْمِكَ الْغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلْقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي وَتَوَفَّنِي إِذَا كَانَتْ الْوَفَاةُ خَيْرًا لِي أَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ وَكَلِمَةَ الْحَقِّ فِي الْغَضَبِ وَالرِّضَا وَالْقَصْدَ فِي الْفَقْرِ وَالْغِنَى وَلَذَّةَ النَّظَرِ إِلَى وَجْهِكَ وَالشَّوْقَ إِلَى لِقَائِكَ وَأَعُوذُ بِكَ مِنْ ضَرَّاءَ مُضِرَّةٍ وَمِنْ فِتْنَةٍ مُضِلَّةٍ اللَّهُمَّ ‏ ‏زَيِّنَّا بِزِينَةِ الْإِيمَانِ وَاجْعَلْنَا هُدَاةً مَهْدِيِّينَ ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدِ بْنِ مُحَمَّدِ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ خُثَيْمٍ أَبُو يَزِيدَ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ يَاسِرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَنَا ‏ ‏وَعَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏رَفِيقَيْنِ فِي غَزْوَةِ ‏ ‏الْعُشَيْرَةِ فَمَرَرْنَا بِرِجَالٍ مِنْ ‏ ‏بَنِي مُدْلِجٍ ‏ ‏يَعْمَلُونَ فِي نَخْلٍ لَهُمْ فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏عِيسَى بْنِ يُونُسَ ‏","","",""],[17606,17606,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ مُحَمَّدِ بْنِ عَمَّارِ بْنِ يَاسِرٍ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ يَاسِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ ‏ ‏الْفِطْرَةِ ‏ ‏أَوْ ‏ ‏الْفِطْرَةُ ‏ ‏الْمَضْمَضَةُ ‏ ‏وَالِاسْتِنْشَاقُ وَقَصُّ الشَّارِبِ وَالسِّوَاكُ وَتَقْلِيمُ الْأَظْفَارِ وَغَسْلُ ‏ ‏الْبَرَاجِمِ ‏ ‏وَنَتْفُ الْإِبِطِ ‏ ‏وَالِاسْتِحْدَادُ ‏ ‏وَالِاخْتِتَانُ ‏ ‏وَالِانْتِضَاحُ ‏","","",""],[17607,17607,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏أَبِي مُوسَى ‏ ‏وَعَبْدِ اللَّهِ ‏ ‏قَالَ فَقَالَ ‏ ‏أَبُو مُوسَى ‏ ‏يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏أَرَأَيْتَ لَوْ أَنَّ رَجُلًا لَمْ يَجِدْ الْمَاءَ وَقَدْ أَجْنَبَ شَهْرًا مَا كَانَ يَتَيَمَّمُ قَالَ لَا وَلَوْ لَمْ يَجِدْ الْمَاءَ شَهْرًا قَالَ فَقَالَ لَهُ ‏ ‏أَبُو مُوسَى ‏ ‏فَكَيْفَ تَصْنَعُونَ بِهَذِهِ الْآيَةِ فِي سُورَةِ ‏ ‏الْمَائِدَةِ ‏ { ‏فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا ‏} ‏قَالَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَوْ رُخِّصَ لَهُمْ فِي هَذَا لَأَوْشَكُوا إِذَا بَرَدَ عَلَيْهِمْ الْمَاءُ أَنْ يَتَيَمَّمُوا ‏ ‏الصَّعِيدَ ‏ ‏ثُمَّ يُصَلُّوا قَالَ فَقَالَ لَهُ ‏ ‏أَبُو مُوسَى ‏ ‏إِنَّمَا كَرِهْتُمْ ذَا لِهَذَا قَالَ نَعَمْ قَالَ لَهُ ‏ ‏أَبُو مُوسَى ‏ ‏أَلَمْ تَسْمَعْ لِقَوْلِ ‏ ‏عَمَّارٍ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ فَأَجْنَبْتُ فَلَمْ أَجِدْ الْمَاءَ فَتَمَرَّغْتُ فِي ‏ ‏الصَّعِيدِ ‏ ‏كَمَا تَمَرَّغُ الدَّابَّةُ ثُمَّ أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ إِنَّمَا كَانَ ‏ ‏يَكْفِيكَ أَنْ تَقُولَ وَضَرَبَ بِيَدِهِ عَلَى الْأَرْضِ ثُمَّ مَسَحَ كُلَّ وَاحِدَةٍ مِنْهُمَا بِصَاحِبَتِهَا ثُمَّ مَسَحَ بِهَا وَجْهَهُ لَمْ يُجِزْ ‏ ‏الْأَعْمَشُ ‏ ‏الْكَفَّيْنِ قَالَ فَقَالَ لَهُ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَلَمْ تَزْعُمُوا لَمْ يَقْنَعْ بِقَوْلِ ‏ ‏عَمَّارٍ ‏ ‏وَقَالَ ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏مَرَّةً قَالَ فَضَرَبَ بِيَدِهِ عَلَى الْأَرْضِ ثُمَّ نَفَضَهَا ثُمَّ ضَرَبَ بِشِمَالِهِ عَلَى يَمِينِهِ وَبِيَمِينِهِ عَلَى شِمَالِهِ ‏ ‏عَلَى الْكَفَّيْنِ ثُمَّ مَسَحَ وَجْهَهُ ‏","","",""],[17608,17608,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏حَدَّثَنَا ‏ ‏شَقِيقٌ ‏ ‏قَالَ ‏ ‏كُنْتُ قَاعِدًا مَعَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَأَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏فَقَالَ ‏ ‏أَبُو مُوسَى ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏لَوْ أَنَّ رَجُلًا لَمْ يَجِدْ الْمَاءَ لَمْ يُصَلِّ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَا فَقَالَ ‏ ‏أَبُو مُوسَى ‏ ‏أَمَا تَذْكُرُ إِذْ قَالَ ‏ ‏عَمَّارٌ ‏ ‏لِعُمَرَ ‏ ‏أَلَا تَذْكُرُ إِذْ بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِيَّاكَ فِي إِبِلٍ فَأَصَابَتْنِي جَنَابَةٌ فَتَمَرَّغْتُ فِي التُّرَابِ فَلَمَّا رَجَعْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرْتُهُ فَضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ إِنَّمَا كَانَ ‏ ‏يَكْفِيكَ أَنْ تَقُولَ هَكَذَا وَضَرَبَ بِكَفَّيْهِ إِلَى الْأَرْضِ ثُمَّ مَسَحَ كَفَّيْهِ جَمِيعًا وَمَسَحَ وَجْهَهُ مَسْحَةً وَاحِدَةً بِضَرْبَةٍ وَاحِدَةٍ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَا جَرَمَ مَا رَأَيْتُ ‏ ‏عُمَرَ ‏ ‏قَنَعَ بِذَلِكَ قَالَ فَقَالَ لَهُ ‏ ‏أَبُو مُوسَى ‏ ‏فَكَيْفَ بِهَذِهِ الْآيَةِ فِي سُورَةِ ‏ ‏النِّسَاءِ ‏ { ‏فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا ‏ ‏صَعِيدًا ‏ ‏طَيِّبًا ‏} ‏قَالَ ‏ ‏فَمَا دَرَى ‏ ‏عَبْدُ اللَّهِ ‏ ‏مَا يَقُولُ وَقَالَ ‏ ‏لَوْ رَخَّصْنَا لَهُمْ فِي التَّيَمُّمِ لَأَوْشَكَ أَحَدُهُمْ إِنْ بَرَدَ الْمَاءُ عَلَى جِلْدِهِ أَنْ يَتَيَمَّمَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَأَنْكَرَهُ ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏فَسَأَلْتُ ‏ ‏حَفْصَ بْنَ غِيَاثٍ ‏ ‏فَقَالَ ‏ ‏كَانَ ‏ ‏الْأَعْمَشُ ‏ ‏يُحَدِّثُنَا ‏ ‏بِهِ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏وَذَكَرَ ‏ ‏أَبَا وَائِلٍ ‏","","",""],[17609,17609,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏لِعَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏إِنْ لَمْ نَجِدْ الْمَاءَ لَا نُصَلِّي قَالَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏نَعَمْ ‏ ‏إِنْ لَمْ نَجِدْ الْمَاءَ شَهْرًا لَمْ نُصَلِّ وَلَوْ رَخَّصْتُ لَهُمْ فِي هَذَا كَانَ إِذَا وَجَدَ أَحَدُهُمْ الْبَرْدَ قَالَ هَكَذَا ‏ ‏يَعْنِي تَيَمَّمَ ‏ ‏وَصَلَّى قَالَ فَقُلْتُ لَهُ فَأَيْنَ قَوْلُ ‏ ‏عَمَّارٍ ‏ ‏لِعُمَرَ ‏ ‏قَالَ إِنِّي لَمْ أَرَ ‏ ‏عُمَرَ ‏ ‏قَنَعَ بِقَوْلِ ‏ ‏عَمَّارٍ ‏","","",""],[17610,17610,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏قَالَ ‏ ‏لَمَّا بَعَثَ ‏ ‏عَلِيٌّ ‏ ‏عَمَّارًا ‏ ‏وَالْحَسَنَ ‏ ‏إِلَى ‏ ‏الْكُوفَةِ ‏ ‏لِيَسْتَنْفِرَاهُمْ ‏ ‏فَخَطَبَ ‏ ‏عَمَّارٌ ‏ ‏فَقَالَ ‏ ‏إِنِّي لَأَعْلَمُ أَنَّهَا زَوْجَتُهُ فِي الدُّنْيَا وَالْآخِرَةِ وَلَكِنَّ اللَّهَ عَزَّ وَجَلَّ ابْتَلَاكُمْ لِتَتَّبِعُوهُ ‏ ‏أَوْ إِيَّاهَا ‏","","",""],[17611,17611,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا أَتَى ‏ ‏عُمَرَ ‏ ‏فَقَالَ إِنِّي أَجْنَبْتُ فَلَمْ أَجِدْ مَاءً فَقَالَ ‏ ‏عُمَرُ ‏ ‏لَا تُصَلِّ فَقَالَ ‏ ‏عَمَّارٌ ‏ ‏أَمَا تَذْكُرُ يَا أَمِيرَ الْمُؤْمِنِينَ إِذْ أَنَا وَأَنْتَ فِي ‏ ‏سَرِيَّةٍ ‏ ‏فَأَجْنَبْنَا فَلَمْ نَجِدْ مَاءً فَأَمَّا أَنْتَ فَلَمْ تُصَلِّ وَأَمَّا أَنَا ‏ ‏فَتَمَعَّكْتُ ‏ ‏فِي التُّرَابِ فَصَلَّيْتُ فَلَمَّا أَتَيْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ إِنَّمَا كَانَ ‏ ‏يَكْفِيكَ وَضَرَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ إِلَى الْأَرْضِ ثُمَّ نَفَخَ فِيهَا وَمَسَحَ بِهَا وَجْهَهُ وَكَفَّيْهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا أَتَى ‏ ‏عُمَرَ ‏ ‏فَذَكَرَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏الْحَكَمِ ‏ ‏وَزَادَ ‏ ‏قَالَ ‏ ‏وَسَلَمَةُ ‏ ‏شَكَّ قَالَ لَا أَدْرِي قَالَ فِيهِ الْمِرْفَقَيْنِ أَوْ إِلَى الْكَفَّيْنِ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏بَلَى ‏ ‏نُوَلِّيكَ مَا تَوَلَّيْتَ ‏","","",""],[17612,17612,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَأَبِي مُوسَى ‏ ‏فَقَالَ ‏ ‏أَبُو مُوسَى ‏ ‏يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏الرَّجُلُ يُجْنِبُ وَلَا يَجِدُ الْمَاءَ ‏ ‏أَيُصَلِّي قَالَ لَا قَالَ أَلَمْ تَسْمَعْ قَوْلَ ‏ ‏عَمَّارٍ ‏ ‏لِعُمَرَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَنَا أَنَا وَأَنْتَ فَأَجْنَبْتُ ‏ ‏فَتَمَعَّكْتُ ‏ ‏بِالصَّعِيدِ ‏ ‏فَأَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْنَاهُ فَقَالَ إِنَّمَا كَانَ ‏ ‏يَكْفِيكَ هَكَذَا وَمَسَحَ وَجْهَهُ وَكَفَّيْهِ وَاحِدَةً ‏ ‏فَقَالَ ‏ ‏إِنِّي لَمْ أَرَ ‏ ‏عُمَرَ ‏ ‏قَنَعَ بِذَلِكَ قَالَ فَكَيْفَ تَصْنَعُونَ بِهَذِهِ الْآيَةِ ‏ { ‏فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا ‏ ‏صَعِيدًا ‏ ‏طَيِّبًا ‏} ‏قَالَ إِنَّا لَوْ رَخَّصْنَا لَهُمْ فِي هَذَا كَانَ أَحَدُهُمْ إِذَا وَجَدَ الْمَاءَ الْبَارِدَ تَمَسَّحَ ‏ ‏بِالصَّعِيدِ ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏فَقُلْتُ ‏ ‏لِشَقِيقٍ ‏ ‏فَمَا كَرِهَهُ إِلَّا لِهَذَا ‏","","",""],[17613,17613,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي مَرَرْتُ بِأَخٍ لِي مِنْ ‏ ‏بَنِي قُرَيْظَةَ ‏ ‏فَكَتَبَ لِي ‏ ‏جَوَامِعَ ‏ ‏مِنْ التَّوْرَاةِ أَلَا أَعْرِضُهَا عَلَيْكَ قَالَ فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ ثَابِتٍ ‏ ‏فَقُلْتُ ‏ ‏لَهُ أَلَا ‏ ‏تَرَى مَا بِوَجْهِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِينَا بِاللَّهِ تَعَالَى رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَسُولًا قَالَ فَسُرِّيَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَوْ أَصْبَحَ فِيكُمْ ‏ ‏مُوسَى ‏ ‏ثُمَّ اتَّبَعْتُمُوهُ وَتَرَكْتُمُونِي لَضَلَلْتُمْ إِنَّكُمْ حَظِّي مِنْ الْأُمَمِ وَأَنَا حَظُّكُمْ مِنْ النَّبِيِّينَ ‏","","",""],[17614,17614,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ حِمَارٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ الْتَقَطَ ‏ ‏لُقَطَةً ‏ ‏فَلْيُشْهِدْ ذَا عَدْلٍ ‏ ‏أَوْ ذَوَيْ عَدْلٍ ‏ ‏ثُمَّ لَا يَكْتُمْ وَلَا ‏ ‏يُغَيِّبْ ‏ ‏فَإِنْ جَاءَ ‏ ‏رَبُّهَا ‏ ‏فَهُوَ أَحَقُّ بِهَا وَإِلَّا فَإِنَّمَا هُوَ مَالُ اللَّهِ ‏ ‏يُؤْتِيهِ مَنْ يَشَاءُ ‏","","",""],[17615,17615,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ حِمَارٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِثْمُ ‏ ‏الْمُسْتَبَّيْنِ ‏ ‏مَا قَالَا عَلَى الْبَادِئِ مَا لَمْ يَعْتَدْ الْمَظْلُومُ ‏ ‏وَالْمُسْتَبَّانِ ‏ ‏شَيْطَانَانِ يَتَكَاذَبَانِ ‏ ‏وَيَتَهَاتَرَانِ ‏","","",""],[17616,17616,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ حِمَارٍ الْمُجَاشِعِيِّ ‏ ‏رَفَعَ الْحَدِيثَ قَالَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏أَمَرَنِي أَنْ أُعَلِّمَكُمْ مَا جَهِلْتُمْ مِمَّا عَلَّمَنِي يَوْمِي هَذَا وَإِنَّهُ قَالَ إِنَّ كُلَّ مَالٍ نَحَلْتُهُ عِبَادِي فَهُوَ لَهُمْ حَلَالٌ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَقَالَ وَأَهْلُ النَّارِ خَمْسَةٌ الضَّعِيفُ الَّذِي لَا ‏ ‏زَبْرَ ‏ ‏لَهُ الَّذِينَ هُمْ فِيكُمْ تَبَعٌ لَا ‏ ‏يَبْتَغُونَ ‏ ‏أَهْلًا وَلَا مَالًا ‏","","",""],[17617,17617,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏حَكِيمٍ الْأَثْرَمِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُطَرِّفُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عِيَاضُ بْنُ حِمَارٍ الْمُجَاشِعِيُّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي خُطْبَةٍ خَطَبَهَا قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏أَمَرَنِي أَنْ أُعَلِّمَكُمْ مَا جَهِلْتُمْ مِمَّا عَلَّمَنِي يَوْمِي هَذَا قَالَ وَإِنَّ كُلَّ مَالٍ ‏ ‏نَحَلْتُهُ ‏ ‏عِبَادِي فَهُوَ لَهُمْ حَلَالٌ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[17618,17618,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ زِيَادٍ الْعَدَوِيُّ ‏ ‏وَحَدَّثَنِي ‏ ‏يَزِيدُ ‏ ‏أَخُو ‏ ‏مُطَرِّفٍ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏عُقْبَةُ ‏ ‏كُلُّ هَؤُلَاءِ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏مُطَرِّفٌ ‏ ‏أَنَّ ‏ ‏عِيَاضَ بْنَ حِمَارٍ ‏ ‏حَدَّثَهُ أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي خُطْبَتِهِ إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏أَمَرَنِي أَنْ أُعَلِّمَكُمْ مَا جَهِلْتُمْ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏وَقَالَ الضَّعِيفُ الَّذِي لَا ‏ ‏زَبْرَ ‏ ‏لَهُ الَّذِينَ هُمْ فِيكُمْ تَبَعٌ لَا ‏ ‏يَبْتَغُونَ ‏ ‏أَهْلًا وَلَا مَالًا ‏ ‏قَالَ قَالَ رَجُلٌ ‏ ‏لِمُطَرِّفٍ ‏ ‏يَا ‏ ‏أَبَا عَبْدِ اللَّهِ ‏ ‏أَمِنَ ‏ ‏الْمَوَالِي ‏ ‏هُوَ أَوْ مِنْ ‏ ‏الْعَرَبِ ‏ ‏قَالَ هُوَ ‏ ‏التَّابِعَةُ ‏ ‏يَكُونُ لِلرَّجُلِ ‏ ‏يُصِيبُ ‏ ‏مِنْ خَدَمِهِ سِفَاحًا غَيْرَ نِكَاحٍ ‏ ‏وَقَالَ أَهْلُ الْجَنَّةِ ثَلَاثَةٌ ذُو سُلْطَانٍ ‏ ‏مُقْسِطٌ ‏ ‏مُصَدِّقٌ مُوقِنٌ وَرَجُلٌ رَحِيمٌ رَقِيقُ الْقَلْبِ بِكُلِّ ذِي قُرْبَى وَمُسْلِمٍ وَرَجُلٌ عَفِيفٌ فَقِيرٌ مُتَصَدِّقٌ ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏قَالَ ‏ ‏بَعْضُ أَصْحَابِ ‏ ‏قَتَادَةَ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا قَالَ ‏ ‏يُونُسُ الْإِسْكَافُ ‏ ‏قَالَ لِي إِنَّ ‏ ‏قَتَادَةَ ‏ ‏لَمْ يَسْمَعْ حَدِيثَ ‏ ‏عِيَاضِ بْنِ حِمَارٍ ‏ ‏مِنْ ‏ ‏مُطَرِّفٍ ‏ ‏قُلْتُ هُوَ حَدَّثَنَا عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏وَتَقُولُ أَنْتَ لَمْ يَسْمَعْهُ مِنْ ‏ ‏مُطَرِّفٍ ‏ ‏قَالَ فَجَاءَ أَعْرَابِيٌّ فَجَعَلَ يَسْأَلُهُ ‏ ‏وَاجْتَرَأَ ‏ ‏عَلَيْهِ قَالَ فَقُلْنَا لِلْأَعْرَابِيِّ سَلْهُ هَلْ سَمِعَ حَدِيثَ ‏ ‏عِيَاضِ بْنِ حِمَارٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏فَسَأَلَهُ فَقَالَ لَا حَدَّثَنِي أَرْبَعَةٌ عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏فَسَمَّى ثَلَاثَةً الَّذِي قُلْتُ لَكُمْ ‏","","",""],[17619,17619,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏أَخِي ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ حِمَارٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِثْمُ ‏ ‏الْمُسْتَبَّيْنِ ‏ ‏مَا قَالَا عَلَى الْبَادِئِ حَتَّى يَفْتَدِيَ الْمَظْلُومُ ‏ ‏أَوْ مَا لَمْ يَفْتَدِ الْمَظْلُومُ ‏","","",""],[17620,17620,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُسْتَبَّانِ ‏ ‏شَيْطَانَانِ يَتَكَاذَبَانِ ‏ ‏وَيَتَهَاتَرَانِ ‏","","",""],[17621,17621,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَالِدًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ حِمَارٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ الْتَقَطَ ‏ ‏لُقَطَةً ‏ ‏فَلْيُشْهِدْ ذَوَيْ عَدْلٍ ‏ ‏أَوْ ذَا عَدْلٍ ‏ ‏خَالِدٌ ‏ ‏الشَّاكُّ ‏ ‏وَلَا يَكْتُمْ وَلَا ‏ ‏يُغَيِّبْ ‏ ‏فَإِنْ جَاءَ ‏ ‏صَاحِبُهَا فَهُوَ أَحَقُّ بِهَا وَإِلَّا فَهُوَ مَالُ اللَّهِ ‏ ‏يُؤْتِيهِ مَنْ يَشَاءُ ‏ ‏قَالَ ‏ ‏سَمِعْت ‏ ‏يَحْيَى بْنَ سَعِيدٍ ‏ ‏يَقُولُ ‏ ‏مُطَرِّفٌ ‏ ‏أَكْبَرُ مِنْ ‏ ‏الْحَسَنِ ‏ ‏بِعِشْرِينَ سَنَةً ‏ ‏وَأَبُو الْعَلَاءِ ‏ ‏أَكْبَرُ مِنْ ‏ ‏الْحَسَنِ ‏ ‏بِعَشْرِ سِنِينَ ‏ ‏حَدَّثَنِيهِ ‏ ‏أَخٌّ لِأَبِي بَكْرِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي عَقِيلٍ الدَّوْرَقِيِّ ‏ ‏بِهَذَا ‏","","",""],[17622,17622,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ الْكَاتِبِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ حَافَظَ عَلَى الصَّلَوَاتِ الْخَمْسِ رُكُوعِهِنَّ وَسُجُودِهِنَّ وَوُضُوئِهِنَّ وَمَوَاقِيتِهِنَّ وَعَلِمَ أَنَّهُنَّ حَقٌّ مِنْ عِنْدِ اللَّهِ دَخَلَ الْجَنَّةَ ‏ ‏أَوْ قَالَ وَجَبَتْ لَهُ الْجَنَّةُ ‏","","",""],[17623,17623,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ الْأُسَيْدِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَافَظَ عَلَى الصَّلَوَاتِ الْخَمْسِ عَلَى وُضُوئِهَا وَمَوَاقِيتِهَا وَرُكُوعِهَا وَسُجُودِهَا يَرَاهَا حَقًّا لِلَّهِ عَلَيْهِ حُرِّمَ عَلَى النَّارِ ‏","","",""],[17624,17624,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ ‏ ‏وَالشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَلَالٌ بَيِّنٌ وَحَرَامٌ بَيِّنٌ وَشُبُهَاتٌ بَيْنَ ذَلِكَ مَنْ تَرَكَ الشُّبُهَاتِ فَهُوَ لِلْحَرَامِ أَتْرَكُ وَمَحَارِمُ اللَّهِ ‏ ‏حِمًى ‏ ‏فَمَنْ ‏ ‏أَرْتَعَ ‏ ‏حَوْلَ ‏ ‏الْحِمَى ‏ ‏كَانَ قَمِنًا أَنْ ‏ ‏يَرْتَعَ ‏ ‏فِيهِ ‏","","",""],[17625,17625,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ ‏ ‏وَالشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ النَّاسِ ‏ ‏قَرْنِي ‏ ‏ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ يَأْتِي قَوْمٌ تَسْبِقُ أَيْمَانُهُمْ شَهَادَتَهُمْ وَشَهَادَتُهُمْ أَيْمَانَهُمْ ‏","","",""],[17626,17626,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ هَذِهِ الْأُمَّةِ ‏ ‏الْقَرْنُ ‏ ‏الَّذِينَ بُعِثْتُ فِيهِمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَ الَّذِينَ يَلُونَهُمْ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏ثُمَّ يَنْشَأُ أَقْوَامٌ تَسْبِقُ أَيْمَانُهُمْ شَهَادَتَهُمْ وَشَهَادَتُهُمْ أَيْمَانَهُمْ ‏","","",""],[17627,17627,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏رَفَعَهُ قَالَ ‏ ‏إِنَّ مِنْ الزَّبِيبِ خَمْرًا وَمِنْ التَّمْرِ خَمْرًا وَمِنْ ‏ ‏الْحِنْطَةِ ‏ ‏خَمْرًا وَمِنْ الشَّعِيرِ خَمْرًا وَمِنْ الْعَسَلِ خَمْرًا ‏","","",""],[17628,17628,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏فَذَكَرَ حَدِيثًا ‏ ‏قَالَ وَحَدَّثَ عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏كَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ ثُمَّ يَسْأَلُ ثُمَّ ‏ ‏يُصَلِّي رَكْعَتَيْنِ ثُمَّ يَسْأَلُ حَتَّى ‏ ‏انْجَلَتْ ‏ ‏الشَّمْسُ قَالَ فَقَالَ ‏ ‏إِنَّ نَاسًا مِنْ أَهْلِ الْجَاهِلِيَّةِ يَقُولُونَ ‏ ‏أَوْ يَزْعُمُونَ ‏ ‏أَنَّ الشَّمْسَ وَالْقَمَرَ إِذَا انْكَسَفَ وَاحِدٌ مِنْهُمَا فَإِنَّمَا يَنْكَسِفُ لِمَوْتِ عَظِيمٍ مِنْ عُظَمَاءِ أَهْلِ الْأَرْضِ وَإِنَّ ذَاكَ لَيْسَ كَذَلِكَ وَلَكِنَّهُمَا خَلْقَانِ مِنْ خَلْقِ اللَّهِ فَإِذَا ‏ ‏تَجَلَّى ‏ ‏اللَّهُ عَزَّ وَجَلَّ لِشَيْءٍ مِنْ خَلْقِهِ خَشَعَ لَهُ ‏","","",""],[17629,17629,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏وَمَنْصُورٍ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنْ ‏ ‏يُسَيْعٍ الْكِنْدِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الدُّعَاءَ هُوَ الْعِبَادَةُ ثُمَّ قَرَأَ ‏ { ‏ادْعُونِي أَسْتَجِبْ لَكُمْ إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِي ‏}","","",""],[17630,17630,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْعَوَّامِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏مِنْ آلِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ فِي الْمَسْجِدِ بَعْدَ صَلَاةِ الْعِشَاءِ رَفَعَ بَصَرَهُ إِلَى السَّمَاءِ ثُمَّ خَفَضَ حَتَّى ظَنَنَّا أَنَّهُ قَدْ حَدَثَ فِي السَّمَاءِ شَيْءٌ فَقَالَ أَلَا ‏ ‏إِنَّهُ سَيَكُونُ بَعْدِي أُمَرَاءُ يَكْذِبُونَ وَيَظْلِمُونَ فَمَنْ صَدَّقَهُمْ بِكَذِبِهِمْ وَمَالَأَهُمْ عَلَى ظُلْمِهِمْ فَلَيْسَ مِنِّي ‏ ‏وَلَا أَنَا مِنْهُ وَمَنْ لَمْ يُصَدِّقْهُمْ بِكَذِبِهِمْ وَلَمْ يُمَالِئْهُمْ عَلَى ظُلْمِهِمْ فَهُوَ مِنِّي وَأَنَا مِنْهُ أَلَا وَإِنَّ دَمَ الْمُسْلِمِ كَفَّارَتُهُ أَلَا وَإِنَّ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ هُنَّ الْبَاقِيَاتُ الصَّالِحَاتُ ‏","","",""],[17631,17631,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏أَنَّ أَبَاهُ ‏ ‏نَحَلَهُ ‏ ‏نُحْلًا ‏ ‏فَقَالَتْ لَهُ ‏ ‏أُمُّ النُّعْمَانِ ‏ ‏أَشْهِدْ لِابْنِي عَلَى هَذَا ‏ ‏النُّحْلِ ‏ ‏فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ذَلِكَ لَهُ فَقَالَ لَهُ ‏ ‏أَوَكُلَّ وَلَدِكَ أَعْطَيْتَ مَا أَعْطَيْتَ هَذَا قَالَ لَا قَالَ فَكَرِهَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَشْهَدَ لَهُ ‏","","",""],[17632,17632,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُؤْمِنِ كَمَثَلِ الْجَسَدِ إِذَا اشْتَكَى الرَّجُلُ رَأْسَهُ ‏ ‏تَدَاعَى ‏ ‏لَهُ سَائِرُ جَسَدِهِ ‏","","",""],[17633,17633,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏النُّعْمَانُ بْنُ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏عَلَى مِنْبَرِ ‏ ‏الْكُوفَةِ ‏ ‏وَاللَّهِ مَا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ نَبِيُّكُمْ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يَشْبَعُ مِنْ ‏ ‏الدَّقَلِ ‏ ‏وَمَا تَرْضَوْنَ دُونَ أَلْوَانِ التَّمْرِ وَالزُّبْدِ ‏","","",""],[17634,17634,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَخْطُبُ وَهُوَ يَقُولُ أَحْمَدُ اللَّهَ تَعَالَى فَرُبَّمَا ‏ ‏أَتَى عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ يَظَلُّ يَتَلَوَّى مَا يَشْبَعُ مِنْ ‏ ‏الدَّقَلِ ‏","","",""],[17635,17635,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏وَحُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏ذَهَبَ أَبِي ‏ ‏بَشِيرُ بْنُ سَعْدٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُشْهِدَهُ عَلَى ‏ ‏نُحْلٍ ‏ ‏نَحَلَنِيهِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكُلَّ بَنِيكَ ‏ ‏نَحَلْتَ ‏ ‏مِثْلَ هَذَا قَالَ لَا قَالَ فَأَرْجِعْهَا ‏","","",""],[17636,17636,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏فِطْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الضُّحَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏انْطَلَقَ بِي أَبِي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي يُشْهِدُهُ عَلَى عَطِيَّةٍ ‏ ‏يُعْطِينِيهَا فَقَالَ ‏ ‏هَلْ لَكَ وَلَدٌ غَيْرُهُ قَالَ نَعَمْ قَالَ فَسَوِّ بَيْنَهُمْ ‏","","",""],[17637,17637,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏النُّعْمَانَ ‏ ‏يَخْطُبُ وَعَلَيْهِ ‏ ‏خَمِيصَةٌ ‏ ‏لَهُ فَقَالَ لَقَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ وَهُوَ يَقُولُ ‏ ‏أَنْذَرْتُكُمْ النَّارَ فَلَوْ أَنَّ رَجُلًا مَوْضِعَ كَذَا وَكَذَا سَمِعَ صَوْتَهُ ‏","","",""],[17638,17638,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْقَائِمِ عَلَى حُدُودِ اللَّهِ تَعَالَى ‏ ‏وَالْمُدَّهِنِ ‏ ‏فِيهَا كَمَثَلِ قَوْمٍ ‏ ‏اسْتَهَمُوا ‏ ‏عَلَى سَفِينَةٍ فِي الْبَحْرِ فَأَصَابَ بَعْضُهُمْ أَسْفَلَهَا وَأَصَابَ بَعْضُهُمْ أَعْلَاهَا فَكَانَ الَّذِينَ فِي أَسْفَلِهَا يَصْعَدُونَ فَيَسْتَقُونَ الْمَاءَ فَيَصُبُّونَ عَلَى الَّذِينَ فِي أَعْلَاهَا فَقَالَ الَّذِينَ فِي أَعْلَاهَا لَا نَدَعُكُمْ تَصْعَدُونَ فَتُؤْذُونَنَا فَقَالَ الَّذِينَ فِي أَسْفَلِهَا فَإِنَّنَا نَنْقُبُهَا مِنْ أَسْفَلِهَا ‏ ‏فَنَسْتَقِي قَالَ فَإِنْ أَخَذُوا عَلَى أَيْدِيهِمْ فَمَنَعُوهُمْ نَجَوْا جَمِيعًا وَإِنْ تَرَكُوهُمْ غَرِقُوا جَمِيعًا ‏","","",""],[17639,17639,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى يَعْنِي ابْنَ مُسْلِمٍ الطَّحَّانَ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِينَ يَذْكُرُونَ مِنْ جَلَالِ اللَّهِ مِنْ تَسْبِيحِهِ وَتَحْمِيدِهِ وَتَكْبِيرِهِ وَتَهْلِيلِهِ ‏ ‏يَتَعَاطَفْنَ ‏ ‏حَوْلَ الْعَرْشِ لَهُنَّ ‏ ‏دَوِيٌّ ‏ ‏كَدَوِيِّ ‏ ‏النَّحْلِ يُذَكِّرُونَ بِصَاحِبِهِنَّ أَلَا يُحِبُّ أَحَدُكُمْ أَنْ لَا يَزَالَ لَهُ عِنْدَ اللَّهِ شَيْءٌ يُذَكِّرُ بِهِ ‏","","",""],[17640,17640,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو حَيَّانَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏سَأَلَتْ أُمِّي أَبِي بَعْضَ الْمَوْهِبَةِ لِي فَوَهَبَهَا لِي فَقَالَتْ لَا ‏ ‏أَرْضَى حَتَّى تُشْهِدَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَخَذَ أَبِي بِيَدِي وَأَنَا غُلَامٌ وَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ أُمَّ هَذَا ‏ ‏ابْنَةَ رَوَاحَةَ ‏ ‏زَاوَلَتْنِي ‏ ‏عَلَى بَعْضِ الْمَوْهِبَةِ لَهُ وَإِنِّي قَدْ وَهَبْتُهَا لَهُ وَقَدْ أَعْجَبَهَا أَنْ أُشْهِدَكَ قَالَ يَا ‏ ‏بَشِيْرُ ‏ ‏أَلَكَ ابْنٌ غَيْرُ هَذَا قَالَ نَعَمْ قَالَ قَالَ ‏ ‏فَوَهَبْتَ لَهُ مِثْلَ الَّذِي وَهَبْتَ لِهَذَا قَالَ لَا قَالَ فَلَا تُشْهِدْنِي إِذًا فَإِنِّي لَا أَشْهَدُ عَلَى ‏ ‏جَوْرٍ ‏","","",""],[17641,17641,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏حُسَيْنُ بْنُ وَاقِدٍ ‏ ‏حَدَّثَنِي ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الصَّفِّ الْأَوَّلِ ‏ ‏أَوْ الصُّفُوفِ ‏ ‏الْأُوَلِ ‏","","",""],[17642,17642,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏انْكَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجَ فَكَانَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ وَيَسْأَلُ وَيُصَلِّي رَكْعَتَيْنِ وَيَسْأَلُ حَتَّى ‏ ‏انْجَلَتْ ‏ ‏فَقَالَ ‏ ‏إِنَّ رِجَالًا يَزْعُمُونَ أَنَّ الشَّمْسَ وَالْقَمَرَ إِذَا انْكَسَفَ وَاحِدٌ مِنْهُمَا فَإِنَّمَا يَنْكَسِفُ لِمَوْتِ عَظِيمٍ مِنْ الْعُظَمَاءِ وَلَيْسَ كَذَلِكَ وَلَكِنَّهُمَا خَلْقَانِ مِنْ خَلْقِ اللَّهِ عَزَّ وَجَلَّ فَإِذَا تَجَلَّى اللَّهُ عَزَّ وَجَلَّ لِشَيْءٍ مِنْ خَلْقِهِ خَشَعَ لَهُ ‏","","",""],[17643,17643,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏حَمَلَنِي أَبِي ‏ ‏بَشِيرُ بْنُ سَعْدٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ اشْهَدْ أَنِّي قَدْ ‏ ‏نَحَلْتُ ‏ ‏النُّعْمَانَ ‏ ‏كَذَا وَكَذَا شَيْئًا سَمَّاهُ قَالَ فَقَالَ ‏ ‏أَكُلَّ وَلَدِكَ ‏ ‏نَحَلْتَ ‏ ‏مِثْلَ الَّذِي ‏ ‏نَحَلْتَ ‏ ‏النُّعْمَانَ ‏ ‏قَالَ لَا قَالَ فَأَشْهِدْ غَيْرِي ثُمَّ قَالَ أَلَيْسَ يَسُرُّكَ أَنْ يَكُونُوا إِلَيْكَ فِي ‏ ‏الْبِرِّ ‏ ‏سَوَاءً قَالَ بَلَى قَالَ فَلَا إِذًا ‏","","",""],[17644,17644,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏كَتَبَ إِلَيَّ ‏ ‏الرَّبِيعُ بْنُ نَافِعٍ أَبُو تَوْبَةَ يَعْنِي الْحَلَبِيَّ ‏ ‏فَكَانَ فِي كِتَابِهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ سَلَّامٍ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏زَيْدِ بْنِ سَلَّامٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَلَّامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏النُّعْمَانُ بْنُ بَشِيرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ إِلَى جَانِبِ مِنْبَرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏رَجُلٌ ‏ ‏مَا ‏ ‏أُبَالِ ‏ ‏أَنْ لَا أَعْمَلَ بَعْدَ الْإِسْلَامِ إِلَّا أَنْ أَسْقِيَ الْحَاجَّ وَقَالَ ‏ ‏آخَرُ ‏ ‏مَا ‏ ‏أُبَالِ ‏ ‏أَنْ لَا أَعْمَلَ عَمَلًا بَعْدَ الْإِسْلَامِ إِلَّا أَنْ أَعْمُرَ ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏ ‏وَقَالَ ‏ ‏آخَرُ ‏ ‏الْجِهَادُ فِي سَبِيلِ اللَّهِ أَفْضَلُ مِمَّا قُلْتُمْ ‏ ‏فَزَجَرَهُمْ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقَالَ لَا تَرْفَعُوا أَصْوَاتَكُمْ عِنْدَ مِنْبَرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَوْمُ الْجُمُعَةِ وَلَكِنْ إِذَا صَلَّيْتُ الْجُمُعَةَ دَخَلْتُ ‏ ‏فَاسْتَفْتَيْتُهُ ‏ ‏فِيمَا اخْتَلَفْتُمْ فِيهِ فَأَنْزَلَ اللَّهُ ‏ { ‏أَجَعَلْتُمْ ‏ ‏سِقَايَةَ ‏ ‏الْحَاجِّ وَعِمَارَةَ ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ ‏كَمَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏} ‏إِلَى آخِرِ الْآيَةِ كُلِّهَا ‏","","",""],[17645,17645,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَوْمَأَ ‏ ‏بِإِصْبَعَيْهِ إِلَى أُذُنَيْهِ ‏ ‏إِنَّ الْحَلَالَ بَيِّنٌ وَالْحَرَامَ بَيِّنٌ وَإِنَّ بَيْنَ الْحَلَالِ وَالْحَرَامِ مُشْتَبِهَاتٍ لَا يَدْرِي كَثِيرٌ مِنْ النَّاسِ أَمِنَ الْحَلَالِ هِيَ أَمْ مِنْ الْحَرَامِ فَمَنْ تَرَكَهَا اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ وَمَنْ وَاقَعَهَا يُوشِكُ أَنْ يُوَاقِعَ الْحَرَامَ فَمَنْ رَعَى إِلَى ‏ ‏جَنْبِ ‏ ‏حِمًى ‏ ‏يُوشِكُ أَنْ ‏ ‏يَرْتَعَ ‏ ‏فِيهِ وَلِكُلِّ مَلِكٍ ‏ ‏حِمًى ‏ ‏وَإِنَّ ‏ ‏حِمَى ‏ ‏اللَّهِ ‏ ‏مَحَارِمُهُ ‏","","",""],[17646,17646,"","","‏ ‏قَالَ وَسَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَبِي ‏ ‏بَشِيرًا ‏ ‏وَهَبَ لِي هِبَةً فَقَالَتْ أُمِّي أَشْهِدْ عَلَيْهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَ بِيَدِي فَانْطَلَقَ بِي حَتَّى أَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ أُمَّ هَذَا الْغُلَامِ سَأَلَتْنِي أَنْ أَهَبَ لَهُ هِبَةً فَوَهَبْتُهَا لَهُ فَقَالَتْ أَشْهِدْ عَلَيْهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَيْتُكَ لِأُشْهِدَكَ فَقَالَ رُوَيْدَكَ أَلَكَ وَلَدٌ غَيْرُهُ قَالَ نَعَمْ قَالَ كُلُّهُمْ أَعْطَيْتَهُ كَمَا أَعْطَيْتَهُ قَالَ لَا قَالَ فَلَا تُشْهِدْنِي إِذًا إِنِّي ‏ ‏لَا أَشْهَدُ عَلَى ‏ ‏جَوْرٍ ‏ ‏إِنَّ لِبَنِيكَ عَلَيْكَ مِنْ الْحَقِّ أَنْ تَعْدِلَ بَيْنَهُمْ ‏","","",""],[17647,17647,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَامِرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَخْطُبُ يَقُولُ وَأَوْمَأَ بِأُصْبُعِهِ إِلَى أُذُنَيْهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَثَلُ الْقَائِمِ عَلَى ‏ ‏حُدُودِ ‏ ‏اللَّهِ وَالْوَاقِعِ فِيهَا ‏ ‏أَوْ ‏ ‏الْمُدَّهِنِ ‏ ‏فِيهَا ‏ ‏مَثَلُ قَوْمٍ رَكِبُوا سَفِينَةً فَأَصَابَ بَعْضُهُمْ أَسْفَلَهَا ‏ ‏وَأَوْعَرَهَا ‏ ‏وَشَرَّهَا وَأَصَابَ بَعْضُهُمْ أَعْلَاهَا فَكَانَ الَّذِينَ فِي أَسْفَلِهَا إِذَا اسْتَقَوْا الْمَاءَ مَرُّوا عَلَى مَنْ فَوْقَهُمْ فَآذَوْهُمْ فَقَالُوا لَوْ خَرَقْنَا فِي نَصِيبِنَا خَرْقًا فَاسْتَقَيْنَا مِنْهُ وَلَمْ نُؤْذِ مَنْ فَوْقَنَا فَإِنْ تَرَكُوهُمْ وَأَمْرَهُمْ هَلَكُوا جَمِيعًا وَإِنْ أَخَذُوا عَلَى أَيْدِيهِمْ نَجَوْا جَمِيعًا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْقَائِمِ عَلَى حُدُودِ اللَّهِ ‏ ‏فَذَكَرَهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَامِرًا ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْقَائِمِ عَلَى حُدُودِ اللَّهِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[17648,17648,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَامِرٌ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَخْطُبُ يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَثَلُ الْمُؤْمِنِينَ فِي تَوَادِّهِمْ وَتَعَاطُفِهِمْ وَتَرَاحُمِهِمْ مَثَلُ الْجَسَدِ إِذَا اشْتَكَى مِنْهُ شَيْءٌ تَدَاعَى لَهُ سَائِرُ الْجَسَدِ بِالسَّهَرِ وَالْحُمَّى ‏","","",""],[17649,17649,"","","‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْحَلَالَ بَيِّنٌ وَالْحَرَامَ بَيِّنٌ وَبَيْنَهُمَا مُشْتَبِهَاتٌ لَا يَعْلَمُهَا كَثِيرٌ مِنْ النَّاسِ فَمَنْ اتَّقَى الشُّبُهَاتِ اسْتَبْرَأَ فِيهِ لِدِينِهِ وَعِرْضِهِ وَمَنْ وَاقَعَهَا وَاقَعَ الْحَرَامَ كَالرَّاعِي ‏ ‏يَرْعَى حَوْلَ ‏ ‏الْحِمَى ‏ ‏يُوشِكُ أَنْ ‏ ‏يَرْتَعَ ‏ ‏فِيهِ أَلَا وَإِنَّ لِكُلِّ مَلِكٍ ‏ ‏حِمًى ‏ ‏وَإِنَّ ‏ ‏حِمَى ‏ ‏اللَّهِ مَا حَرَّمَ أَلَا وَإِنَّ فِي الْإِنْسَانِ ‏ ‏مُضْغَةً ‏ ‏إِذَا صَلُحَتْ صَلُحَ الْجَسَدُ كُلُّهُ وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ أَلَا وَهِيَ الْقَلْبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَامِرًا ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُؤْمِنِينَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[17650,17650,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَوِّي بَيْنَ الصُّفُوفِ كَمَا ‏ ‏تُسَوَّى ‏ ‏الْقِدَاحُ ‏ ‏أَوْ الرِّمَاحُ ‏","","",""],[17651,17651,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏أَنَا أَعْلَمُ النَّاسِ ‏ ‏أَوْ كَأَعْلَمِ النَّاسِ ‏ ‏بِوَقْتِ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْعِشَاءِ كَانَ ‏ ‏يُصَلِّيهَا بَعْدَ سُقُوطِ الْقَمَرِ فِي اللَّيْلَةِ الثَّالِثَةِ مِنْ أَوَّلِ الشَّهْرِ ‏","","",""],[17652,17652,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏سَيَّارٌ ‏ ‏وَأَخْبَرَنَا ‏ ‏مُغِيرَةُ ‏ ‏وَأَخْبَرَنَا ‏ ‏دَاوُدُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏وَإِسْمَاعِيلُ بْنُ سَالِمٍ ‏ ‏وَمُجَالِدٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏نَحَلَنِي ‏ ‏أَبِي ‏ ‏نُحْلًا ‏ ‏قَالَ ‏ ‏إِسْمَاعِيلُ بْنُ سَالِمٍ ‏ ‏مِنْ بَيْنِ الْقَوْمِ ‏ ‏نَحَلَهُ ‏ ‏غُلَامًا ‏ ‏قَالَ فَقَالَتْ لَهُ أُمِّي ‏ ‏عَمْرَةُ بِنْتُ رَوَاحَةَ ‏ ‏ائْتِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَشْهِدْهُ قَالَ فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ذَلِكَ لَهُ فَقَالَ إِنِّي ‏ ‏نَحَلْتُ ‏ ‏ابْنِي ‏ ‏النُّعْمَانَ ‏ ‏نُحْلًا ‏ ‏وَإِنَّ ‏ ‏عَمْرَةَ ‏ ‏سَأَلَتْنِي أَنْ أُشْهِدَكَ عَلَى ذَلِكَ فَقَالَ أَلَكَ وَلَدٌ سِوَاهُ قَالَ قُلْتُ نَعَمْ قَالَ فَكُلَّهُمْ أَعْطَيْتَ مِثْلَ مَا أَعْطَيْتَ ‏ ‏النُّعْمَانَ ‏ ‏فَقَالَ لَا فَقَالَ بَعْضُ هَؤُلَاءِ الْمُحَدِّثِينَ ‏ ‏هَذَا ‏ ‏جَوْرٌ ‏ ‏وَقَالَ بَعْضُهُمْ هَذَا تَلْجِئَةٌ ‏ ‏فَأَشْهِدْ عَلَى هَذَا غَيْرِي ‏ ‏وَقَالَ ‏ ‏مُغِيرَةُ ‏ ‏فِي حَدِيثِهِ أَلَيْسَ يَسُرُّكَ أَنْ يَكُونُوا لَكَ فِي الْبِرِّ وَاللُّطْفِ سَوَاءً قَالَ نَعَمْ قَالَ فَأَشْهِدْ عَلَى هَذَا غَيْرِي ‏ ‏وَذَكَرَ ‏ ‏مُجَالِدٌ ‏ ‏فِي حَدِيثِهِ إِنَّ لَهُمْ عَلَيْكَ مِنْ الْحَقِّ أَنْ تَعْدِلَ بَيْنَهُمْ كَمَا أَنَّ لَكَ عَلَيْهِمْ مِنْ الْحَقِّ أَنْ يَبَرُّوكَ ‏","","",""],[17653,17653,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ أَبِي زَائِدَةَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الْقَائِمِ عَلَى ‏ ‏حُدُودِ ‏ ‏اللَّهِ تَعَالَى ‏ ‏وَالرَّاتِعِ ‏ ‏فِيهَا ‏ ‏وَالْمُدَّهِنِ ‏ ‏فِيهَا مَثَلُ قَوْمٍ ‏ ‏اسْتَهَمُوا ‏ ‏عَلَى سَفِينَةٍ فَأَصَابَ بَعْضُهُمْ أَعْلَاهَا وَأَصَابَ بَعْضُهُمْ أَسْفَلَهَا ‏ ‏وَأَوْعَرَهَا ‏ ‏وَإِذَا الَّذِينَ أَسْفَلَهَا إِذَا اسْتَقَوْا مِنْ الْمَاءِ مَرُّوا عَلَى أَصْحَابِهِمْ فَآذَوْهُمْ فَقَالُوا لَوْ أَنَّا خَرَقْنَا فِي نَصِيبِنَا خَرْقًا فَاسْتَقَيْنَا مِنْهُ وَلَمْ نَمُرَّ عَلَى أَصْحَابِنَا فَنُؤْذِيَهُمْ فَإِنْ تَرَكُوهُمْ وَمَا أَرَادُوا هَلَكُوا وَإِنْ أَخَذُوا عَلَى أَيْدِيهِمْ نَجَوْا جَمِيعًا ‏","","",""],[17654,17654,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَثَلُ الْمُؤْمِنِينَ فِي تَوَادِّهِمْ وَتَعَاطُفِهِمْ وَتَرَاحُمِهِمْ مَثَلُ الْجَسَدِ إِذَا اشْتَكَى مِنْهُ عُضْوٌ تَدَاعَى سَائِرُ الْجَسَدِ بِالسَّهَرِ وَالْحُمَّى ‏","","",""],[17655,17655,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏الضَّحَّاكَ بْنَ قَيْسٍ ‏ ‏سَأَلَ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏بِمَ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الْجُمُعَةِ مَعَ سُورَةِ ‏ ‏الْجُمُعَةِ ‏ ‏قَالَ ‏ ‏هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ ‏","","",""],[17656,17656,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏وَحُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَخْبَرَاهُ أَنَّهُمَا سَمِعَا ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏نَحَلَنِي ‏ ‏أَبِي غُلَامًا فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأُشْهِدَهُ فَقَالَ ‏ ‏أَكُلَّ وَلَدِكَ قَدْ ‏ ‏نَحَلْتَ ‏ ‏قَالَ لَا قَالَ فَارْدُدْهُ ‏","","",""],[17657,17657,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ يَعْنِي ابْنَ مُحَمَّدِ بْنِ الْمُنْتَشِرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَ فِي الْعِيدَيْنِ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَهَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ ‏ ‏وَإِنْ وَافَقَ يَوْمَ الْجُمُعَةِ قَرَأَهُمَا جَمِيعًا ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏حَبِيبُ بْنُ سَالِمٍ ‏ ‏سَمِعَهُ مِنَ ‏ ‏النُّعْمَانِ ‏ ‏وَكَانَ كَاتِبَهُ ‏ ‏وَسُفْيَانُ ‏ ‏يُخْطِئُ فِيهِ يَقُولُ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنْ أَبِيهِ وَهُوَ سَمِعَهُ مِنْ ‏ ‏النُّعْمَانِ ‏","","",""],[17658,17658,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏حَفِظْتُهُ مِنْ ‏ ‏أَبِي فَرْوَةَ ‏ ‏أَوَّلًا ثُمَّ مِنْ ‏ ‏مُجَالِدٍ ‏ ‏سَمِعَهُ مِنَ ‏ ‏الشَّعْبِيِّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكُنْتُ إِذَا سَمِعْتُهُ يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصْغَيْتُ وَتَقَرَّبْتُ وَخَشِيتُ أَنْ لَا أَسْمَعَ أَحَدًا يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏حَلَالٌ بَيِّنٌ وَحَرَامٌ بَيِّنٌ وَشُبُهَاتٌ بَيْنَ ذَلِكَ مَنْ تَرَكَ مَا اشْتَبَهَ عَلَيْهِ مِنْ الْإِثْمِ كَانَ لِمَا ‏ ‏اسْتَبَانَ ‏ ‏لَهُ أَتْرَكَ وَمَنْ ‏ ‏اجْتَرَأَ ‏ ‏عَلَى مَا شَكَّ فِيهِ أَوْشَكَ أَنْ يُوَاقِعَ الْحَرَامَ وَإِنَّ لِكُلِّ مَلِكٍ حِمًى وَإِنَّ حِمَى اللَّهِ فِي الْأَرْضِ مَعَاصِيهِ ‏ ‏أَوْ قَالَ مَحَارِمُهُ ‏","","",""],[17659,17659,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقِيمُ الصُّفُوفَ كَمَا تُقَامُ الرِّمَاحُ ‏ ‏أَوْ ‏ ‏الْقِدَاحُ ‏","","",""],[17660,17660,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنْ ‏ ‏يُسَيْعٍ الْكِنْدِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الدُّعَاءَ هُوَ الْعِبَادَةُ ثُمَّ قَرَأَ ‏ { ‏وَقَالَ رَبُّكُمْ ادْعُونِي أَسْتَجِبْ لَكُمْ إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِي سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ ‏} ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏يُسَيْعٌ الْكِنْدِيُّ يُسَيْعُ بْنُ مَعْدَانَ ‏","","",""],[17661,17661,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقْرَأُ فِي صَلَاةِ الْجُمُعَةِ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَهَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ ‏ ‏فَرُبَّمَا اجْتَمَعَ الْعِيدُ وَالْجُمُعَةُ فَقَرَأَ بِهَاتَيْنِ السُّورَتَيْنِ ‏","","",""],[17662,17662,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي عِيسَى مُوسَى الصَّغِيرِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَوْنُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الَّذِينَ يَذْكُرُونَ مِنْ جَلَالِ اللَّهِ وَتَسْبِيحِهِ وَتَحْمِيدِهِ وَتَهْلِيلِهِ تَتَعَطَّفُ حَوْلَ الْعَرْشِ لَهُنَّ ‏ ‏دَوِيٌّ ‏ ‏كَدَوِيِّ ‏ ‏النَّحْلِ يُذَكِّرُونَ بِصَاحِبِهِنَّ أَفَلَا يُحِبُّ أَحَدُكُمْ أَنْ لَا يَزَالَ لَهُ عِنْدَ اللَّهِ شَيْءٌ يُذَكِّرُ بِهِ ‏","","",""],[17663,17663,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمَ بْنَ أَبِي الْجَعْدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَتُسَوُّنَّ صُفُوفَكُمْ أَوْ لَيُخَالِفَنَّ اللَّهُ بَيْنَ وُجُوهِكُمْ ‏","","",""],[17664,17664,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَخْطُبُ وَهُوَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَهْوَنَ أَهْلِ النَّارِ عَذَابًا يَوْمَ الْقِيَامَةِ رَجُلٌ يُجْعَلُ فِي ‏ ‏أَخْمَصِ ‏ ‏قَدَمَيْهِ نَعْلَانِ مِنْ نَارٍ يَغْلِي مِنْهُمَا دِمَاغُهُ ‏","","",""],[17665,17665,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنْ ‏ ‏يُسَيْعٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الدُّعَاءُ هُوَ الْعِبَادَةُ ثُمَّ قَرَأَ ‏ { ‏ادْعُونِي أَسْتَجِبْ لَكُمْ ‏}","","",""],[17666,17666,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي كُسُوفِ الشَّمْسِ نَحْوًا مِنْ صَلَاتِكُمْ يَرْكَعُ وَيَسْجُدُ ‏","","",""],[17667,17667,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُؤْمِنُونَ كَرَجُلٍ وَاحِدٍ إِنْ اشْتَكَى رَأْسُهُ اشْتَكَى كُلُّهُ وَإِنْ اشْتَكَى عَيْنُهُ اشْتَكَى كُلُّهُ ‏","","",""],[17668,17668,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْعِيزَارِ بْنِ حُرَيْثٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَسْتَأْذِنُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعَ ‏ ‏عَائِشَةَ ‏ ‏وَهِيَ رَافِعَةٌ صَوْتَهَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَذِنَ لَهُ فَدَخَلَ فَقَالَ يَا ‏ ‏ابْنَةَ أُمِّ رُومَانَ ‏ ‏وَتَنَاوَلَهَا أَتَرْفَعِينَ صَوْتَكِ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَحَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَهُ وَبَيْنَهَا قَالَ فَلَمَّا خَرَجَ ‏ ‏أَبُو بَكْرٍ ‏ ‏جَعَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ لَهَا ‏ ‏يَتَرَضَّاهَا ‏ ‏أَلَا تَرَيْنَ أَنِّي قَدْ حُلْتُ بَيْنَ الرَّجُلِ وَبَيْنَكِ قَالَ ثُمَّ جَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَاسْتَأْذَنَ عَلَيْهِ فَوَجَدَهُ يُضَاحِكُهَا قَالَ فَأَذِنَ لَهُ فَدَخَلَ فَقَالَ لَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا رَسُولَ اللَّهِ أَشْرِكَانِي فِي سِلْمِكُمَا كَمَا أَشْرَكْتُمَانِي فِي حَرْبِكُمَا ‏","","",""],[17669,17669,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي عَازِبٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ شَيْءٍ خَطَأٌ إِلَّا السَّيْفَ وَلِكُلِّ خَطَإٍ ‏ ‏أَرْشٌ ‏","","",""],[17670,17670,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَعْلَمُ النَّاسِ ‏ ‏أَوْ مِنْ أَعْلَمِ النَّاسِ ‏ ‏بِوَقْتِ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِشَاءَ كَانَ ‏ ‏يُصَلِّيهَا مِقْدَارَ مَا يَغِيبُ الْقَمَرُ لَيْلَةَ ثَالِثَةٍ ‏ ‏أَوْ رَابِعَةٍ ‏","","",""],[17671,17671,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏وَأَبُو الْعَلَاءِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏قَالَ ‏ ‏رُفِعَ إِلَى ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏رَجُلٌ أَحَلَّتْ لَهُ امْرَأَتُهُ جَارِيَتَهَا فَقَالَ لَأَقْضِيَنَّ فِيهَا بِقَضِيَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَئِنْ كَانَتْ أَحَلَّتْهَا لَهُ لَأَجْلِدَنَّهُ مِائَةَ جَلْدَةٍ وَإِنْ لَمْ تَكُنْ أَحَلَّتْهَا لَهُ لَأَرْجُمَنَّهُ قَالَ ‏ ‏فَوَجَدَهَا قَدْ أَحَلَّتْهَا لَهُ فَجَلَدَهُ مِائَةً ‏","","",""],[17672,17672,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَخْطُبُ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ يَقُولُ ‏ ‏أَنْذَرْتُكُمْ النَّارَ أَنْذَرْتُكُمْ النَّارَ أَنْذَرْتُكُمْ النَّارَ حَتَّى لَوْ أَنَّ رَجُلًا كَانَ بِالسُّوقِ لَسَمِعَهُ مِنْ مَقَامِي هَذَا قَالَ حَتَّى وَقَعَتْ ‏ ‏خَمِيصَةٌ ‏ ‏كَانَتْ عَلَى عَاتِقِهِ عِنْدَ رِجْلَيْهِ ‏","","",""],[17673,17673,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْذَرْتُكُمْ النَّارَ أَنْذَرْتُكُمْ النَّارَ حَتَّى لَوْ كَانَ رَجُلٌ كَانَ فِي أَقْصَى السُّوقِ سَمِعَهُ وَسَمِعَ أَهْلُ السُّوقِ صَوْتَهُ وَهُوَ عَلَى الْمِنْبَرِ ‏","","",""],[17674,17674,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَوِّينَا فِي الصُّفُوفِ حَتَّى كَأَنَّمَا ‏ ‏يُحَاذِي بِنَا ‏ ‏الْقِدَاحَ ‏ ‏فَلَمَّا أَرَادَ أَنْ يُكَبِّرَ رَأَى رَجُلًا ‏ ‏شَاخِصًا ‏ ‏صَدْرُهُ فَقَالَ ‏ ‏لَتُسَوُّنَّ صُفُوفَكُمْ أَوْ لَيُخَالِفَنَّ اللَّهُ بَيْنَ وُجُوهِكُمْ ‏","","",""],[17675,17675,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ ‏ ‏الْمُجَاهِدِ ‏ ‏فِي سَبِيلِ اللَّهِ كَمَثَلِ الصَّائِمِ نَهَارَهُ وَالْقَائِمِ لَيْلَهُ حَتَّى يَرْجِعَ مَتَى يَرْجِعُ ‏","","",""],[17676,17676,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏نُعَيْمُ بْنُ زِيَادٍ أَبُو طَلْحَةَ الْأَنْمَارِيُّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ عَلَى مِنْبَرِ ‏ ‏حِمْصَ ‏ ‏قُمْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ ثَلَاثٍ وَعِشْرِينَ فِي شَهْرِ رَمَضَانَ إِلَى ثُلُثِ اللَّيْلِ الْأَوَّلِ ثُمَّ قُمْنَا مَعَهُ لَيْلَةَ خَمْسٍ وَعِشْرِينَ إِلَى نِصْفِ اللَّيْلِ ثُمَّ قَامَ بِنَا لَيْلَةَ سَبْعٍ وَعِشْرِينَ حَتَّى ظَنَنَّا أَنْ لَا نُدْرِكَ الْفَلَاحَ قَالَ وَكُنَّا ‏ ‏نَدْعُو السُّحُورَ الْفَلَاحَ ‏ ‏فَأَمَّا نَحْنُ ‏ ‏فَنَقُولُ ‏ ‏لَيْلَةُ السَّابِعَةِ لَيْلَةُ سَبْعٍ وَعِشْرِينَ وَأَنْتُمْ تَقُولُونَ لَيْلَةُ ثَلَاثٍ وَعِشْرِينَ السَّابِعَةُ فَمَنْ أَصَوْبُ نَحْنُ أَوْ أَنْتُمْ ‏","","",""],[17677,17677,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ وَاقِدٍ ‏ ‏حَدَّثَنِي ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ مَنَحَ مَنِيحَةً وَرِقًا أَوْ ذَهَبًا أَوْ سَقَى لَبَنًا أَوْ أَهْدَى ‏ ‏زِقَاقًا ‏ ‏فَهُوَ كَعَدْلِ رَقَبَةٍ ‏","","",""],[17678,17678,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏صَحِبْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَمِعْنَاهُ يَقُولُ ‏ ‏إِنَّ بَيْنَ يَدَيْ السَّاعَةِ فِتَنًا كَأَنَّهَا قِطَعُ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ ‏ ‏فِيهَا مُؤْمِنًا ثُمَّ يُمْسِي كَافِرًا ‏ ‏وَيُمْسِي مُؤْمِنًا ثُمَّ يُصْبِحُ كَافِرًا يَبِيعُ أَقْوَامٌ خَلَاقَهُمْ بِعَرَضٍ مِنْ الدُّنْيَا يَسِيرٍ ‏ ‏أَوْ بِعَرَضِ الدُّنْيَا ‏ ‏قَالَ ‏ ‏الْحَسَنُ ‏ ‏وَاللَّهِ ‏ ‏لَقَدْ رَأَيْنَاهُمْ صُوَرًا وَلَا عُقُولَ أَجْسَامًا وَلَا أَحْلَامَ فَرَاشَ نَارٍ ‏ ‏وَذِبَّانَ طَمَعٍ يَغْدُونَ بِدِرْهَمَيْنِ وَيَرُوحُونَ بِدِرْهَمَيْنِ يَبِيعُ أَحَدُهُمْ دَيْنَهُ بِثَمَنِ الْعَنْزِ ‏","","",""],[17679,17679,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏جَاءَتْ امْرَأَةٌ إِلَى ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏فَقَالَتْ إِنَّ زَوْجَهَا وَقَعَ عَلَى ‏ ‏جَارِيَتِهَا ‏ ‏فَقَالَ ‏ ‏سَأَقْضِي فِي ذَلِكَ بِقَضَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كُنْتِ ‏ ‏أَحْلَلْتِيهَا لَهُ ضَرَبْتُهُ مِائَةَ سَوْطٍ وَإِنْ لَمْ تَكُونِي ‏ ‏أَحْلَلْتِيهَا لَهُ ‏ ‏رَجَمْتُهُ ‏","","",""],[17680,17680,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنِي ‏ ‏دَاوُدُ بْنُ إِبْرَاهِيمَ الْوَاسِطِيُّ ‏ ‏حَدَّثَنِي ‏ ‏حَبِيبُ بْنُ سَالِمٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏كُنَّا قُعُودًا فِي الْمَسْجِدِ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ ‏ ‏بَشِيرٌ ‏ ‏رَجُلًا ‏ ‏يَكُفُّ ‏ ‏حَدِيثَهُ فَجَاءَ ‏ ‏أَبُو ثَعْلَبَةَ الْخُشَنِيُّ ‏ ‏فَقَالَ يَا ‏ ‏بَشِيرُ بْنَ سَعْدٍ ‏ ‏أَتَحْفَظُ حَدِيثَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْأُمَرَاءِ فَقَالَ ‏ ‏حُذَيْفَةُ ‏ ‏أَنَا أَحْفَظُ خُطْبَتَهُ فَجَلَسَ ‏ ‏أَبُو ثَعْلَبَةَ ‏ ‏فَقَالَ ‏ ‏حُذَيْفَةُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَكُونُ النُّبُوَّةُ فِيكُمْ مَا شَاءَ اللَّهُ أَنْ تَكُونَ ثُمَّ يَرْفَعُهَا إِذَا شَاءَ أَنْ يَرْفَعَهَا ثُمَّ تَكُونُ خِلَافَةٌ عَلَى مِنْهَاجِ النُّبُوَّةِ فَتَكُونُ مَا شَاءَ اللَّهُ أَنْ تَكُونَ ثُمَّ يَرْفَعُهَا إِذَا شَاءَ اللَّهُ أَنْ يَرْفَعَهَا ثُمَّ تَكُونُ مُلْكًا ‏ ‏عَاضًّا ‏ ‏فَيَكُونُ مَا شَاءَ اللَّهُ أَنْ يَكُونَ ثُمَّ يَرْفَعُهَا إِذَا شَاءَ أَنْ يَرْفَعَهَا ثُمَّ تَكُونُ مُلْكًا ‏ ‏جَبْرِيَّةً ‏ ‏فَتَكُونُ مَا شَاءَ اللَّهُ أَنْ تَكُونَ ثُمَّ يَرْفَعُهَا إِذَا شَاءَ أَنْ يَرْفَعَهَا ثُمَّ تَكُونُ خِلَافَةً عَلَى مِنْهَاجِ النُّبُوَّةِ ثُمَّ سَكَتَ ‏ ‏قَالَ ‏ ‏حَبِيبٌ ‏ ‏فَلَمَّا قَامَ ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏وَكَانَ ‏ ‏يَزِيدُ بْنُ النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏فِي صَحَابَتِهِ فَكَتَبْتُ إِلَيْهِ بِهَذَا الْحَدِيثِ أُذَكِّرُهُ إِيَّاهُ فَقُلْتُ لَهُ ‏ ‏إِنِّي أَرْجُو أَنْ يَكُونَ أَمِيرُ الْمُؤْمِنِينَ ‏ ‏يَعْنِي ‏ ‏عُمَرَ ‏ ‏بَعْدَ الْمُلْكِ ‏ ‏الْعَاضِّ ‏ ‏وَالْجَبْرِيَّةِ ‏ ‏فَأُدْخِلَ كِتَابِي عَلَى ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏فَسُرَّ بِهِ وَأَعْجَبَهُ ‏","","",""],[17681,17681,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ كَثِيرٍ الْهَمْدَانِيِّ ‏ ‏أَنَّهُ حَدَّثَهُ أَنَّ ‏ ‏السَّرِيَّ بْنَ إِسْمَاعِيلَ الْكُوفِيَّ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏الشَّعْبِيَّ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ ‏ ‏الْحِنْطَةِ ‏ ‏خَمْرًا وَمِنْ الشَّعِيرِ خَمْرًا وَمِنْ الزَّبِيبِ خَمْرًا وَمِنْ التَّمْرِ خَمْرًا وَمِنْ الْعَسَلِ خَمْرًا وَأَنَا أَنْهَى عَنْ كُلِّ مُسْكِرٍ ‏","","",""],[17682,17682,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَبَهْزٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏أَظُنُّهُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَافَرَ رَجُلٌ بِأَرْضٍ تَنُوفَةٍ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏يَعْنِي ‏ ‏فَلَاةً ‏ ‏فَقَالَ تَحْتَ شَجَرَةٍ وَمَعَهُ ‏ ‏رَاحِلَتُهُ ‏ ‏وَعَلَيْهَا سِقَاؤُهُ وَطَعَامُهُ فَاسْتَيْقَظَ فَلَمْ يَرَهَا فَعَلَا ‏ ‏شَرَفًا ‏ ‏فَلَمْ يَرَهَا ثُمَّ عَلَا ‏ ‏شَرَفًا ‏ ‏فَلَمْ يَرَهَا ثُمَّ الْتَفَتَ فَإِذَا هُوَ بِهَا تَجُرُّ ‏ ‏خِطَامَهَا ‏ ‏فَمَا هُوَ بِأَشَدَّ بِهَا فَرَحًا مِنْ اللَّهِ بِتَوْبَةِ عَبْدِهِ إِذَا تَابَ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏عَبْدِهِ إِذَا تَابَ إِلَيْهِ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَظُنُّهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[17683,17683,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ الْمُنْتَشِرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الْعِيدَيْنِ وَالْجُمُعَةِ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَهَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ ‏ ‏وَرُبَّمَا اجْتَمَعَا فِي يَوْمٍ وَاحِدٍ فَقَرَأَ بِهِمَا ‏ ‏وَقَدْ قَالَ ‏ ‏أَبُو عَوَانَةَ ‏ ‏وَرُبَّمَا اجْتَمَعَ عِيدَانِ فِي يَوْمٍ ‏","","",""],[17684,17684,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏مُجَالِدٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏وَكَانَ أَمِيرًا عَلَى ‏ ‏الْكُوفَةِ ‏ ‏نَحَلَنِي ‏ ‏أَبِي غُلَامًا فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأُشْهِدَهُ فَقَالَ ‏ ‏أَكُلَّ وَلَدِكَ ‏ ‏نَحَلْتَ ‏ ‏قَالَ لَا قَالَ فَإِنِّي لَا أَشْهَدُ عَلَى ‏ ‏جَوْرٍ ‏","","",""],[17685,17685,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏سَمِعَهُ ‏ ‏مِنْ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَثَلُ ‏ ‏الْمُدَّهِنِ ‏ ‏وَالْوَاقِعِ فِي حُدُودِ اللَّهِ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً الْقَائِمِ فِي حُدُودِ اللَّهِ ‏ ‏مَثَلُ ثَلَاثَةٍ رَكِبُوا فِي سَفِينَةٍ فَصَارَ لِأَحَدِهِمْ أَسْفَلُهَا وَأَوْعَرُهَا وَشَرُّهَا فَكَانَ ‏ ‏يَخْتَلِفُ وَثَقُلَ عَلَيْهِ كُلَّمَا مَرَّ فَقَالَ أَخْرِقُ خَرْقًا يَكُونُ أَهْوَنَ عَلَيَّ وَلَا يَكُونُ مُخْتَلَفِي عَلَيْهِمْ فَقَالَ بَعْضُهُمْ إِنَّمَا يَخْرِقُ فِي نَصِيبِهِ وَقَالَ آخَرُونَ لَا فَإِنْ أَخَذُوا عَلَى يَدَيْهِ نَجَا وَنَجَوْا وَإِنْ تَرَكُوهُ هَلَكَ وَهَلَكُوا ‏","","",""],[17686,17686,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏الشَّعْبِيُّ ‏ ‏سَمِعَهُ مِنَ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكُنْتُ إِذَا سَمِعْتُهُ يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ظَنَنْتُ أَنْ لَا أَسْمَعَ أَحَدًا عَلَى الْمِنْبَرِ يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ فِي الْإِنْسَانِ ‏ ‏مُضْغَةً ‏ ‏إِذَا سَلِمَتْ وَصَحَّتْ سَلِمَ سَائِرُ الْجَسَدِ وَصَحَّ وَإِذَا ‏ ‏سَقِمَتْ ‏ ‏سَقِمَ ‏ ‏سَائِرُ الْجَسَدِ وَفَسَدَ أَلَا وَهِيَ الْقَلْبُ ‏","","",""],[17687,17687,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏وَهُوَ يَخْطُبُ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَهْوَنَ أَهْلِ النَّارِ عَذَابًا يَوْمَ الْقِيَامَةِ لَرَجُلٌ يُوضَعُ فِي ‏ ‏أَخْمَصِ ‏ ‏قَدَمَيْهِ جَمْرَتَانِ يَغْلِي مِنْهُمَا دِمَاغُهُ ‏","","",""],[17688,17688,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْأَشْعَثِ بْنِ عَبْدِ الرَّحْمَنِ الْجَرْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ كَتَبَ كِتَابًا قَبْلَ أَنْ يَخْلُقَ السَّمَوَاتِ وَالْأَرْضَ بِأَلْفَيْ عَامٍ فَأَنْزَلَ مِنْهُ آيَتَيْنِ فَخَتَمَ بِهِمَا سُورَةَ ‏ ‏الْبَقَرَةِ ‏ ‏وَلَا يُقْرَأَانِ فِي دَارٍ ثَلَاثَ لَيَالٍ فَيَقْرَبَهَا الشَّيْطَانُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فَلَا تُقْرَبَنَّ ‏","","",""],[17689,17689,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏وَاللَّهِ إِنِّي لَأَعْلَمُ النَّاسِ بِوَقْتِ هَذِهِ الصَّلَاةِ صَلَاةِ الْعِشَاءِ الْآخِرَةِ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّيهَا لِسُقُوطِ الْقَمَرِ لِثَالِثَةٍ ‏","","",""],[17690,17690,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏سُرَيْجٌ ‏ ‏فِي حَدِيثِهِ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَثَلُ الْمُؤْمِنِينَ كَمَثَلِ الْجَسَدِ إِذَا أَلِمَ بَعْضُهُ تَدَاعَى سَائِرُهُ ‏","","",""],[17691,17691,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَبْدِ الْكَرِيمِ بْنِ مَعْقِلِ بْنِ مُنَبِّهٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الصَّمَدِ يَعْنِي ابْنَ مَعْقِلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏وَهْبًا ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏النُّعْمَانُ بْنُ بَشِيرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ ‏ ‏الرَّقِيمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ ثَلَاثَةً كَانُوا فِي كَهْفٍ فَوَقَعَ الْجَبَلُ عَلَى بَابِ الْكَهْفِ ‏ ‏فَأُوصِدَ ‏ ‏عَلَيْهِمْ قَالَ قَائِلٌ مِنْهُمْ تَذَاكَرُوا أَيُّكُمْ عَمِلَ حَسَنَةً لَعَلَّ اللَّهَ عَزَّ وَجَلَّ بِرَحْمَتِهِ يَرْحَمُنَا فَقَالَ رَجُلٌ مِنْهُمْ قَدْ عَمِلْتُ حَسَنَةً مَرَّةً كَانَ لِي أُجَرَاءُ يَعْمَلُونَ فَجَاءَنِي عُمَّالٌ لِي فَاسْتَأْجَرْتُ كُلَّ رَجُلٍ مِنْهُمْ بِأَجْرٍ مَعْلُومٍ فَجَاءَنِي رَجُلٌ ذَاتَ يَوْمٍ وَسَطَ النَّهَارِ فَاسْتَأْجَرْتُهُ ‏ ‏بِشَطْرِ ‏ ‏أَصْحَابِهِ فَعَمِلَ فِي بَقِيَّةِ نَهَارِهِ كَمَا عَمِلَ كُلُّ رَجُلٍ مِنْهُمْ فِي نَهَارِهِ كُلِّهِ فَرَأَيْتُ عَلَيَّ فِي ‏ ‏الزِّمَامِ ‏ ‏أَنْ لَا أُنْقِصَهُ مِمَّا اسْتَأْجَرْتُ بِهِ أَصْحَابَهُ لِمَا جَهِدَ فِي عَمَلِهِ فَقَالَ رَجُلٌ مِنْهُمْ أَتُعْطِي هَذَا مِثْلَ مَا أَعْطَيْتَنِي وَلَمْ يَعْمَلْ إِلَّا نِصْفَ نَهَارٍ فَقُلْتُ يَا عَبْدَ اللَّهِ لَمْ أَبْخَسْكَ شَيْئًا مِنْ شَرْطِكَ وَإِنَّمَا هُوَ مَالِي أَحْكُمُ فِيهِ مَا شِئْتُ قَالَ فَغَضِبَ وَذَهَبَ وَتَرَكَ أَجْرَهُ قَالَ فَوَضَعْتُ حَقَّهُ فِي جَانِبٍ مِنْ الْبَيْتِ مَا شَاءَ اللَّهُ ثُمَّ مَرَّتْ بِي بَعْدَ ذَلِكَ بَقَرٌ فَاشْتَرَيْتُ بِهِ فَصِيلَةً مِنْ الْبَقَرِ فَبَلَغَتْ مَا شَاءَ اللَّهُ فَمَرَّ بِي بَعْدَ حِينٍ شَيْخًا ضَعِيفًا لَا أَعْرِفُهُ فَقَالَ إِنَّ لِي عِنْدَكَ حَقًّا فَذَكَّرَنِيهِ حَتَّى عَرَفْتُهُ فَقُلْتُ إِيَّاكَ ‏ ‏أَبْغِي هَذَا حَقُّكَ فَعَرَضْتُهَا عَلَيْهِ جَمِيعَهَا فَقَالَ يَا عَبْدَ اللَّهِ لَا تَسْخَرْ بِي إِنْ لَمْ تَصَدَّقْ عَلَيَّ فَأَعْطِنِي حَقِّي قَالَ وَاللَّهِ لَا أَسْخَرُ بِكَ إِنَّهَا لَحَقُّكَ مَا لِي مِنْهَا شَيْءٌ فَدَفَعْتُهَا إِلَيْهِ جَمِيعًا اللَّهُمَّ إِنْ كُنْتُ فَعَلْتُ ذَلِكَ لِوَجْهِكَ فَافْرُجْ عَنَّا قَالَ ‏ ‏فَانْصَدَعَ ‏ ‏الْجَبَلُ حَتَّى رَأَوْا مِنْهُ وَأَبْصَرُوا قَالَ الْآخَرُ قَدْ عَمِلْتُ حَسَنَةً مَرَّةً كَانَ لِي ‏ ‏فَضْلٌ ‏ ‏فَأَصَابَتْ النَّاسَ شِدَّةٌ فَجَاءَتْنِي امْرَأَةٌ تَطْلُبُ مِنِّي مَعْرُوفًا قَالَ فَقُلْتُ وَاللَّهِ مَا هُوَ دُونَ نَفْسِكِ فَأَبَتْ عَلَيَّ فَذَهَبَتْ ثُمَّ رَجَعَتْ فَذَكَّرَتْنِي بِاللَّهِ فَأَبَيْتُ عَلَيْهَا وَقُلْتُ لَا وَاللَّهِ مَا هُوَ دُونَ نَفْسِكِ فَأَبَتْ عَلَيَّ وَذَهَبَتْ فَذَكَرَتْ لِزَوْجِهَا فَقَالَ لَهَا أَعْطِيهِ نَفْسَكِ ‏ ‏وَأَغْنِي عِيَالَكِ فَرَجَعَتْ إِلَيَّ فَنَاشَدَتْنِي بِاللَّهِ فَأَبَيْتُ عَلَيْهَا وَقُلْتُ وَاللَّهِ مَا هُوَ دُونَ نَفْسِكِ فَلَمَّا رَأَتْ ذَلِكَ أَسْلَمَتْ إِلَيَّ نَفْسَهَا فَلَمَّا تَكَشَّفْتُهَا وَهَمَمْتُ بِهَا ارْتَعَدَتْ مِنْ تَحْتِي فَقُلْتُ لَهَا مَا شَأْنُكِ قَالَتْ أَخَافُ اللَّهَ رَبَّ الْعَالَمِينَ قُلْتُ لَهَا ‏ ‏خِفْتِيهِ فِي الشِّدَّةِ وَلَمْ أَخَفْهُ فِي الرَّجَاءِ فَتَرَكْتُهَا وَأَعْطَيْتُهَا مَا يَحِقُّ عَلَيَّ بِمَا تَكَشَّفْتُهَا اللَّهُمَّ إِنْ كُنْتُ فَعَلْتُ ذَلِكَ لِوَجْهِكَ فَافْرُجْ عَنَّا قَالَ ‏ ‏فَانْصَدَعَ ‏ ‏حَتَّى عَرَفُوا وَتَبَيَّنَ لَهُمْ قَالَ الْآخَرُ عَمِلْتُ حَسَنَةً مَرَّةً كَانَ لِي أَبَوَانِ شَيْخَانِ كَبِيرَانِ وَكَانَتْ لِي غَنَمٌ فَكُنْتُ أُطْعِمُ أَبَوَيَّ ‏ ‏وَأَسْقِيهِمَا ثُمَّ رَجَعْتُ إِلَى غَنَمِي قَالَ فَأَصَابَنِي يَوْمًا ‏ ‏غَيْثٌ ‏ ‏حَبَسَنِي فَلَمْ أَبْرَحْ حَتَّى أَمْسَيْتُ فَأَتَيْتُ أَهْلِي وَأَخَذْتُ مِحْلَبِي فَحَلَبْتُ وَغَنَمِي قَائِمَةٌ فَمَضَيْتُ إِلَى أَبَوَيَّ فَوَجَدْتُهُمَا قَدْ نَامَا فَشَقَّ عَلَيَّ أَنْ أُوقِظَهُمَا وَشَقَّ عَلَيَّ أَنْ أَتْرُكَ غَنَمِي فَمَا بَرِحْتُ جَالِسًا وَمِحْلَبِي عَلَى يَدِي حَتَّى أَيْقَظَهُمَا الصُّبْحُ فَسَقَيْتُهُمَا اللَّهُمَّ إِنْ كُنْتُ فَعَلْتُ ذَلِكَ لِوَجْهِكَ فَافْرُجْ عَنَّا قَالَ ‏ ‏النُّعْمَانُ ‏ ‏لَكَأَنِّي أَسْمَعُ هَذِهِ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ الْجَبَلُ ‏ ‏طَاقْ ‏ ‏فَفَرَّجَ اللَّهُ عَنْهُمْ فَخَرَجُوا ‏","","",""],[17692,17692,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي فَرْوَةَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَلَالٌ بَيِّنٌ وَحَرَامٌ بَيِّنٌ وَبَيْنَ ذَلِكَ أُمُورٌ مُشْتَبِهَةٌ فَمَنْ تَرَكَ مَا اشْتَبَهَ عَلَيْهِ مِنْ الْإِثْمِ أَوْ الْأَمْرِ فَهُوَ لِمَا ‏ ‏اسْتَبَانَ ‏ ‏لَهُ أَتْرَكُ وَمَنْ ‏ ‏اجْتَرَأَ ‏ ‏عَلَى مَا شَكَّ أَوْشَكَ أَنْ يُوَاقِعَ مَا ‏ ‏اسْتَبَانَ ‏ ‏وَمَنْ ‏ ‏يَرْتَعْ ‏ ‏حَوْلَ ‏ ‏الْحِمَى ‏ ‏يُوشِكْ أَنْ يُوَاقِعَهُ ‏","","",""],[17693,17693,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏حَاجِبِ بْنِ الْمُفَضَّلِ يَعْنِي ابْنَ الْمُهَلَّبِ بْنِ أَبِي صُفْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْدِلُوا بَيْنَ أَبْنَائِكُمْ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏حَدَّثَنِي ‏ ‏الْقَوَارِيرِيُّ ‏ ‏وَالْمُقَدَّمِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏حَاجِبِ بْنِ الْمُفَضَّلِ يَعْنِي ابْنَ الْمُهَلَّبِ بْنِ أَبِي صُفْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْدِلُوا بَيْنَ أَبْنَائِكُمْ ‏","","",""],[17694,17694,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏الْعِيزَارُ بْنُ حُرَيْثٍ ‏ ‏قَالَ قَالَ ‏ ‏النُّعْمَانُ بْنُ بَشِيرٍ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنَ ‏ ‏أَبُو بَكْرٍ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعَ صَوْتَ ‏ ‏عَائِشَةَ ‏ ‏عَالِيًا وَهِيَ تَقُولُ وَاللَّهِ لَقَدْ ‏ ‏عَرَفْتُ أَنَّ ‏ ‏عَلِيًّا ‏ ‏أَحَبُّ إِلَيْكَ مِنْ أَبِي وَمِنِّي مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏فَاسْتَأْذَنَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَدَخَلَ فَأَهْوَى إِلَيْهَا فَقَالَ يَا بِنْتَ فُلَانَةَ أَلَا أَسْمَعُكِ تَرْفَعِينَ صَوْتَكِ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[17695,17695,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏حَاجِبِ بْنِ الْمُفَضَّلِ بْنِ الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَخْطُبُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْدِلُوا بَيْنَ أَبْنَائِكُمْ اعْدِلُوا بَيْنَ أَبْنَائِكُمْ ‏","","",""],[17696,17696,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ يَعْنِي الْحَرَّانِيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ مِنْ رَجُلٍ كَانَ فِي سَفَرٍ فِي ‏ ‏فَلَاةٍ ‏ ‏مِنْ الْأَرْضِ ‏ ‏فَآوَى ‏ ‏إِلَى ظِلِّ شَجَرَةٍ فَنَامَ تَحْتَهَا فَاسْتَيْقَظَ فَلَمْ يَجِدْ رَاحِلَتَهُ فَأَتَى ‏ ‏شَرَفًا ‏ ‏فَصَعِدَ عَلَيْهِ ‏ ‏فَأَشْرَفَ ‏ ‏فَلَمْ يَرَ شَيْئًا ثُمَّ أَتَى آخَرَ ‏ ‏فَأَشْرَفَ ‏ ‏فَلَمْ يَرَ شَيْئًا فَقَالَ أَرْجِعُ إِلَى مَكَانِي الَّذِي كُنْتُ فِيهِ فَأَكُونُ فِيهِ حَتَّى أَمُوتَ قَالَ فَذَهَبَ فَإِذَا ‏ ‏بِرَاحِلَتِهِ ‏ ‏تَجُرُّ ‏ ‏خِطَامَهَا ‏ ‏قَالَ فَاللَّهُ عَزَّ وَجَلَّ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ مِنْ هَذَا ‏ ‏بِرَاحِلَتِهِ ‏","","",""],[17697,17697,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏جَابِرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَازِبٍ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏فِي شَهَادَةٍ فَسَمِعْتُهُ يَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ سَمِعْتُهُ يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كُلُّ شَيْءٍ خَطَأٌ إِلَّا السَّيْفَ وَفِي كُلِّ خَطَإٍ ‏ ‏أَرْشٌ ‏","","",""],[17698,17698,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ وَهُوَ الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنِي ‏ ‏خَالِدُ بْنُ عُرْفُطَةَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏أَنَّ رَجُلًا يُقَالُ لَهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ حُنَيْنٍ ‏ ‏وَكَانَ ‏ ‏يُنْبَزُ ‏ ‏قُرْقُورًا ‏ ‏وَقَعَ ‏ ‏عَلَى ‏ ‏جَارِيَةِ ‏ ‏امْرَأَتِهِ قَالَ فَرُفِعَ إِلَى ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ الْأَنْصَارِيِّ ‏ ‏فَقَالَ لَأَقْضِيَنَّ فِيكَ بِقَضَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كَانَتْ أَحَلَّتْهَا لَكَ جَلَدْتُكَ مِائَةً وَإِنْ لَمْ تَكُنْ أَحَلَّتْهَا لَكَ ‏ ‏رَجَمْتُكَ ‏ ‏بِالْحِجَارَةِ قَالَ وَكَانَتْ قَدْ أَحَلَّتْهَا لَهُ فَجَلَدَهُ مِائَةً ‏ ‏وَقَالَ سَمِعْتُ ‏ ‏أَبَانًا ‏ ‏يَقُولُ وَأَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّهُ كَتَبَ فِيهِ إِلَى ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏وَكَتَبَ إِلَيْهِ بِهَذَا ‏","","",""],[17699,17699,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عُرْفُطَةَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏وَقَالَ ‏ ‏أَبَانُ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّهُ كَتَبَ إِلَى ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏فِيهِ فَكَتَبَ إِلَيْهِ ‏ ‏أَنَّ رَجُلًا يُقَالُ لَهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ حُنَيْنٍ ‏ ‏كَانَ ‏ ‏يُنْبَزُ ‏ ‏قُرْقُورًا رُفِعَ إِلَى ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏وَطِئَ ‏ ‏جَارِيَةَ امْرَأَتِهِ فَقَالَ لَأَقْضِيَنَّ فِيكَ بِقَضَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كَانَتْ أَحَلَّتْهَا لَكَ جَلَدْتُكَ مِائَةً وَإِنْ لَمْ تَكُنْ أَحَلَّتْهَا لَكَ ‏ ‏رَجَمْتُكَ ‏ ‏فَوَجَدَهَا قَدْ أَحَلَّتْهَا لَهُ فَجَلَدَهُ مِائَةً ‏","","",""],[17700,17700,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَوِّينَا فِي الصُّفُوفِ كَمَا تُقَوَّمُ ‏ ‏الْقِدَاحُ ‏ ‏حَتَّى إِذَا ظَنَّ أَنَّا قَدْ أَخَذْنَا ذَلِكَ عَنْهُ وَفَهِمْنَاهُ أَقْبَلَ ذَاتَ يَوْمٍ بِوَجْهِهِ فَإِذَا رَجُلٌ ‏ ‏مُنْتَبِذٌ ‏ ‏بِصَدْرِهِ فَقَالَ ‏ ‏لَتُسَوُّنَّ صُفُوفَكُمْ أَوْ لَيُخَالِفَنَّ اللَّهُ بَيْنَ وُجُوهِكُمْ ‏","","",""],[17701,17701,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ النَّاسِ ‏ ‏قَرْنِي ‏ ‏الَّذِي أَنَا فِيهِ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ يَأْتِي قَوْمٌ تَسْبِقُ شَهَادَتُهُمْ أَيْمَانَهُمْ وَأَيْمَانُهُمْ شَهَادَتَهُمْ ‏","","",""],[17702,17702,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏وَزَكَرِيَّا ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏وَفِطْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏أَنَّ ‏ ‏بَشِيرًا ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَادَ أَنْ ‏ ‏يَنْحَلَ ‏ ‏النُّعْمَانَ ‏ ‏نُحْلًا ‏ ‏قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ لَكَ مِنْ وَلَدٍ سِوَاهُ قَالَ نَعَمْ قَالَ فَكُلَّهُمْ أَعْطَيْتَ مَا أَعْطَيْتَهُ قَالَ لَا ‏ ‏قَالَ ‏ ‏فِطْرٌ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَكَذَا أَيْ سَوِّ بَيْنَهُمْ ‏ ‏وَقَالَ ‏ ‏زَكَرِيَّا ‏ ‏وَإِسْمَاعِيلُ ‏ ‏لَا أَشْهَدُ عَلَى ‏ ‏جَوْرٍ ‏","","",""],[17703,17703,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏أَبِي الْقَاسِمِ الْجَدَلِيِّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏حُسَيْنِ بْنِ الْحَارِثِ أَبِي الْقَاسِمِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏قَالَ ‏ ‏أَقْبَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِوَجْهِهِ عَلَى النَّاسِ فَقَالَ ‏ ‏أَقِيمُوا صُفُوفَكُمْ ثَلَاثًا وَاللَّهِ لَتُقِيمُنَّ صُفُوفَكُمْ أَوْ ‏ ‏لَيُخَالِفَنَّ ‏ ‏اللَّهُ بَيْنَ قُلُوبِكُمْ ‏ ‏قَالَ ‏ ‏فَرَأَيْتُ الرَّجُلَ يُلْزِقُ كَعْبَهُ بِكَعْبِ صَاحِبِهِ وَرُكْبَتَهُ بِرُكْبَتِهِ وَمَنْكِبَهُ بِمَنْكِبِهِ ‏","","",""],[17704,17704,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏قَالَ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ الْمُنْتَشِرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقْرَأُ فِي الْعِيدَيْنِ وَالْجُمُعَةِ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَهَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ ‏","","",""],[17705,17705,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏ذَرٍّ الْهَمْدَانِيِّ ‏ ‏عَنْ ‏ ‏يُسَيْعٍ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الدُّعَاءَ هُوَ الْعِبَادَةُ ثُمَّ قَرَأَ ‏ { ‏وَقَالَ رَبُّكُمْ ادْعُونِي أَسْتَجِبْ لَكُمْ ‏}","","",""],[17706,17706,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُؤْمِنُونَ كَرَجُلٍ وَاحِدٍ إِذَا اشْتَكَى رَأْسُهُ تَدَاعَى لَهُ سَائِرُ الْجَسَدِ بِالْحُمَّى وَالسَّهَرِ ‏","","",""],[17707,17707,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ ‏ ‏خَيْثَمَةُ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُؤْمِنُونَ كَرَجُلٍ وَاحِدٍ إِذَا اشْتَكَى رَأْسُهُ اشْتَكَى كُلُّهُ وَإِنْ اشْتَكَى عَيْنُهُ اشْتَكَى كُلُّهُ ‏","","",""],[17708,17708,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَأَى رَجُلًا خَارِجًا صَدْرُهُ مِنْ الصَّفِّ فَقَالَ ‏ ‏اسْتَوُوا وَلَا تَخْتَلِفُوا فَتَخْتَلِفَ قُلُوبُكُمْ ‏","","",""],[17709,17709,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَالْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنْ ‏ ‏يُسَيْعٍ الْحَضْرَمِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ وَيَقُولُ ‏ ‏إِنَّ الدُّعَاءَ هُوَ الْعِبَادَةُ ثُمَّ قَرَأَ ‏ { ‏وَقَالَ رَبُّكُمْ ادْعُونِي أَسْتَجِبْ لَكُمْ ‏} ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنْ ‏ ‏يُسَيْعٍ الْحَضْرَمِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ نَحْوَهُ كَذَا قَالَ ‏ ‏شُعْبَةُ ‏ ‏مِثْلَهُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏أُخْبِرْتُ أَنَّ ‏ ‏أُسَيْعًا ‏ ‏هُوَ ‏ ‏يُسَيْعُ بْنُ مَعْدَانَ الْحَضْرَمِيُّ ‏","","",""],[17710,17710,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏الضَّحَّاكَ بْنَ قَيْسٍ ‏ ‏سَأَلَ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏بِمَ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الْجُمُعَةِ مَعَ سُورَةِ ‏ ‏الْجُمُعَةِ ‏ ‏قَالَ ‏ ‏هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ ‏","","",""],[17711,17711,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏كَتَبَ إِلَى ‏ ‏قَيْسِ بْنِ الْهَيْثَمِ ‏ ‏إِنَّكُمْ إِخْوَانُنَا وَأَشِقَّاؤُنَا وَإِنَّا شَهِدْنَا وَلَمْ تَشْهَدُوا وَسَمِعْنَا وَلَمْ تَسْمَعُوا وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏إِنَّ بَيْنَ يَدَيْ السَّاعَةِ فِتَنًا كَأَنَّهَا قِطَعُ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ فِيهَا مُؤْمِنًا ‏ ‏وَيُمْسِي كَافِرًا وَيَبِيعُ فِيهَا أَقْوَامٌ خَلَاقَهُمْ بِعَرَضٍ مِنْ الدُّنْيَا ‏","","",""],[17712,17712,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمَ بْنَ أَبِي الْجَعْدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَتُسَوُّنَّ صُفُوفَكُمْ فِي صَلَاتِكُمْ أَوْ لَيُخَالِفَنَّ اللَّهُ بَيْنَ وُجُوهِكُمْ ‏","","",""],[17713,17713,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَوِّي الصَّفَّ حَتَّى يَجْعَلَهُ مِثْلَ الرُّمْحِ أَوْ الْقَدَحِ قَالَ فَرَأَى صَدْرَ رَجُلٍ ‏ ‏نَاتِئًا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا عِبَادَ اللَّهِ ‏ ‏لَتُسَوُّنَّ صُفُوفَكُمْ أَوْ لَيُخَالِفَنَّ اللَّهُ بَيْنَ وُجُوهِكُمْ ‏","","",""],[17714,17714,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَهَاشِمٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ الْمُنْتَشِرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏قَالَ ‏ ‏يَعْنِي فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الْجُمُعَةِ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏فِي صَلَاةِ الْجُمُعَةِ يَوْمَ الْجُمُعَةِ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَهَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ ‏ ‏وَرُبَّمَا اجْتَمَعَ عِيدَانِ فَقَرَأَ بِهِمَا ‏","","",""],[17715,17715,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةِ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏انْكَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْكَعُ وَيَسْجُدُ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏مِثْلَ صَلَاتِنَا ‏","","",""],[17716,17716,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عُرْفُطَةَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي الرَّجُلِ يَأْتِي ‏ ‏جَارِيَةَ ‏ ‏امْرَأَتِهِ قَالَ ‏ ‏إِنْ كَانَتْ أَحَلَّتْهَا لَهُ جَلَدْتُهُ مِائَةً وَإِنْ لَمْ تَكُنْ أَحَلَّتْهَا لَهُ ‏ ‏رَجَمْتُهُ ‏","","",""],[17717,17717,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏مَوْلَى ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏أَنَّهُ رُفِعَ إِلَيْهِ رَجُلٌ ‏ ‏غَشِيَ ‏ ‏جَارِيَةَ ‏ ‏امْرَأَتِهِ فَقَالَ لَأَقْضِيَنَّ فِيهَا بِقَضِيَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كَانَتْ أَحَلَّتْهَا لَكَ جَلَدْتُكَ مِائَةَ جَلْدَةٍ وَإِنْ كَانَتْ لَمْ تُحِلَّهَا لَكَ ‏ ‏رَجَمْتُكَ ‏ ‏قَالَ فَوَجَدَهَا قَدْ كَانَتْ أَحَلَّتْهَا لَهُ فَجَلَدَهُ مِائَةً ‏","","",""],[17718,17718,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ سَالِمٍ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏أَتَتْهُ امْرَأَةٌ فَقَالَتْ إِنَّ زَوْجَهَا ‏ ‏وَقَعَ ‏ ‏عَلَى ‏ ‏جَارِيَتِهَا ‏ ‏قَالَ أَمَا إِنَّ عِنْدِي فِي ذَلِكَ خَبَرًا شَافِيًا أَخَذْتُهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كُنْتِ أَذِنْتِ لَهُ ضَرَبْتُهُ مِائَةً وَإِنْ كُنْتِ لَمْ تَأْذَنِي لَهُ ‏ ‏رَجَمْتُهُ ‏ ‏قَالَ فَأَقْبَلَ النَّاسُ عَلَيْهَا فَقَالُوا زَوْجُكِ ‏ ‏يُرْجَمُ ‏ ‏قُولِي إِنَّكِ قَدْ كُنْتِ أَذِنْتِ لَهُ فَقَالَتْ قَدْ كُنْتُ أَذِنْتُ لَهُ فَقَدَّمَهُ فَضَرَبَهُ مِائَةً ‏","","",""],[17719,17719,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ النَّاسِ ‏ ‏قَرْنِي ‏ ‏ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ قَوْمٌ ‏ ‏تَسْبِقُ شَهَادَتُهُمْ أَيْمَانَهُمْ وَتَسْبِقُ أَيْمَانُهُمْ شَهَادَتَهُمْ ‏","","",""],[17720,17720,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَبْدِ اللَّهِ بْنِ مُعَاوِيَةَ بْنِ عَاصِمِ بْنِ الْمُنْذِرِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏سَلَّامٌ أَبُو الْمُنْذِرِ الْقَارِي ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ بَهْدَلَةَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏أَوْ ‏ ‏خَيْثَمَةَ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا مَثَلُ الْمُسْلِمِينَ كَالرَّجُلِ الْوَاحِدِ إِذَا وَجِعَ مِنْهُ شَيْءٌ تَدَاعَى لَهُ سَائِرُ جَسَدِهِ ‏","","",""],[17721,17721,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ أَبِي مُزَاحِمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو وَكِيعٍ الْجَرَّاحُ بْنُ مَلِيحٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏مَنْ لَمْ يَشْكُرْ الْقَلِيلَ لَمْ يَشْكُرْ الْكَثِيرَ وَمَنْ لَمْ يَشْكُرْ النَّاسَ لَمْ يَشْكُرْ اللَّهَ التَّحَدُّثُ بِنِعْمَةِ اللَّهِ شُكْرٌ وَتَرْكُهَا كُفْرٌ وَالْجَمَاعَةُ رَحْمَةٌ وَالْفُرْقَةُ عَذَابٌ ‏","","",""],[17722,17722,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عَبْدِ اللَّهِ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو وَكِيعٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى هَذِهِ الْأَعْوَادِ ‏ ‏أَوْ عَلَى هَذَا الْمِنْبَرِ ‏ ‏مَنْ لَمْ يَشْكُرْ الْقَلِيلَ لَمْ يَشْكُرْ الْكَثِيرَ وَمَنْ لَمْ يَشْكُرْ النَّاسَ لَمْ يَشْكُرْ اللَّهَ وَالتَّحَدُّثُ بِنِعْمَةِ اللَّهِ شُكْرٌ وَتَرْكُهَا كُفْرٌ وَالْجَمَاعَةُ رَحْمَةٌ وَالْفُرْقَةُ عَذَابٌ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏أَبُو أُمَامَةَ الْبَاهِلِيُّ ‏ ‏عَلَيْكُمْ ‏ ‏بِالسَّوَادِ ‏ ‏الْأَعْظَمِ قَالَ فَقَالَ رَجُلٌ مَا ‏ ‏السَّوَادُ ‏ ‏الْأَعْظَمُ فَقَالَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏هَذِهِ الْآيَةُ فِي سُورَةِ ‏ ‏النُّورِ ‏ { ‏فَإِنْ تَوَلَّوْا فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُمْ مَا حُمِّلْتُمْ ‏}","","",""],[17723,17723,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَاجِبُ بْنُ الْمُفَضَّلِ يَعْنِي ابْنَ الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَارِبُوا بَيْنَ أَبْنَائِكُمْ ‏ ‏يَعْنِي سَوُّوا بَيْنَهُمْ ‏","","",""],[17724,17724,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْحَسَنِ الْبَاهِلِيُّ ‏ ‏وَعُبَيْدُ اللَّهِ الْقَوَارِيرِيُّ ‏ ‏وَمُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏حَاجِبِ بْنِ الْمُفَضَّلِ بْنِ الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْدِلُوا بَيْنَ أَبْنَائِكُمْ اعْدِلُوا بَيْنَ أَبْنَائِكُمْ اعْدِلُوا بَيْنَ أَبْنَائِكُمْ ‏","","",""],[17725,17725,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ شَرِيكٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِذَا أَصْحَابُهُ كَأَنَّمَا عَلَى رُءُوسِهِمْ الطَّيْرُ ‏","","",""],[17726,17726,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ شَرِيكٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ عِنْدَهُ كَأَنَّمَا عَلَى رُءُوسِهِمْ الطَّيْرُ قَالَ فَسَلَّمْتُ عَلَيْهِ وَقَعَدْتُ قَالَ فَجَاءَتْ ‏ ‏الْأَعْرَابُ ‏ ‏فَسَأَلُوهُ فَقَالُوا يَا رَسُولَ اللَّهِ ‏ ‏نَتَدَاوَى قَالَ نَعَمْ ‏ ‏تَدَاوَوْا فَإِنَّ اللَّهَ لَمْ يَضَعْ دَاءً إِلَّا وَضَعَ لَهُ دَوَاءً غَيْرَ دَاءٍ وَاحِدٍ ‏ ‏الْهَرَمُ ‏ ‏قَالَ وَكَانَ ‏ ‏أُسَامَةُ ‏ ‏حِينَ كَبِرَ يَقُولُ هَلْ تَرَوْنَ لِي مِنْ دَوَاءٍ الْآنَ ‏ ‏قَالَ وَسَأَلُوهُ عَنْ أَشْيَاءَ هَلْ عَلَيْنَا حَرَجٌ فِي كَذَا وَكَذَا قَالَ عِبَادَ اللَّهِ وَضَعَ اللَّهُ الْحَرَجَ إِلَّا امْرَأً اقْتَضَى امْرَأً مُسْلِمًا ظُلْمًا فَذَلِكَ حَرَجٌ ‏ ‏وَهُلْكٌ قَالُوا مَا خَيْرُ مَا أُعْطِيَ النَّاسُ يَا رَسُولَ اللَّهِ قَالَ خُلُقٌ حَسَنٌ ‏","","",""],[17727,17727,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ زِيَادٍ يَعْنِي الْمُطَّلِبَ بْنَ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ شَرِيكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَدَاوَوْا عِبَادَ اللَّهِ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَمْ يُنَزِّلْ دَاءً إِلَّا أَنْزَلَ مَعَهُ شِفَاءً إِلَّا الْمَوْتَ وَالْهَرَمَ ‏","","",""],[17728,17728,"","","‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ سَلَّامٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَجْلَحُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ شَرِيكٍ ‏ ‏رَجُلٌ مِنْ قَوْمِهِ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَيُّ النَّاسِ خَيْرٌ قَالَ أَحْسَنُهُمْ خُلُقًا ثُمَّ قَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَنَتَدَاوَى قَالَ ‏ ‏تَدَاوَوْا فَإِنَّ اللَّهَ لَمْ يُنْزِلْ دَاءً إِلَّا أَنْزَلَ لَهُ شِفَاءً عَلِمَهُ مَنْ عَلِمَهُ وَجَهِلَهُ مَنْ جَهِلَهُ ‏","","",""],[17729,17729,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ بْنِ الْمُصْطَلِقِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ أَنْ يَقْرَأَ الْقُرْآنَ ‏ ‏غَضًّا ‏ ‏كَمَا أُنْزِلَ فَلْيَقْرَأْهُ عَلَى قِرَاءَةِ ‏ ‏ابْنِ أُمِّ عَبْدٍ ‏","","",""],[17730,17730,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَإِسْحَاقَ يَعْنِي الْأَزْرَقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ الْحَارِثِ ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏بْنُ الْمُصْطَلِقِ ‏ ‏يَقُولُ ‏ ‏مَا تَرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا سِلَاحَهُ وَبَغْلَةً بَيْضَاءَ وَأَرْضًا جَعَلَهَا صَدَقَةً ‏","","",""],[17731,17731,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَابِقٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ دِينَارٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏أَنَّهُ سَمِعَ ‏ ‏الْحَارِثَ بْنَ أَبِي ضِرَارٍ الْخُزَاعِيِّ ‏ ‏قَالَ ‏ ‏قَدِمْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَانِي إِلَى الْإِسْلَامِ فَدَخَلْتُ فِيهِ وَأَقْرَرْتُ بِهِ فَدَعَانِي إِلَى الزَّكَاةِ فَأَقْرَرْتُ بِهَا وَقُلْتُ يَا رَسُولَ اللَّهِ أَرْجِعُ إِلَى قَوْمِي ‏ ‏فَأَدْعُوهُمْ إِلَى الْإِسْلَامِ وَأَدَاءِ الزَّكَاةِ فَمَنْ اسْتَجَابَ لِي جَمَعْتُ زَكَاتَهُ فَيُرْسِلُ إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَسُولًا ‏ ‏لِإِبَّانِ ‏ ‏كَذَا وَكَذَا لِيَأْتِيَكَ مَا جَمَعْتُ مِنْ الزَّكَاةِ فَلَمَّا جَمَعَ ‏ ‏الْحَارِثُ ‏ ‏الزَّكَاةَ مِمَّنْ اسْتَجَابَ لَهُ وَبَلَغَ ‏ ‏الْإِبَّانَ ‏ ‏الَّذِي أَرَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُبْعَثَ إِلَيْهِ ‏ ‏احْتَبَسَ ‏ ‏عَلَيْهِ الرَّسُولُ فَلَمْ يَأْتِهِ فَظَنَّ ‏ ‏الْحَارِثُ ‏ ‏أَنَّهُ قَدْ حَدَثَ فِيهِ سَخْطَةٌ مِنْ اللَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ فَدَعَا ‏ ‏بِسَرَوَاتِ ‏ ‏قَوْمِهِ فَقَالَ لَهُمْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ وَقَّتَ لِي وَقْتًا يُرْسِلُ إِلَيَّ رَسُولَهُ لِيَقْبِضَ مَا كَانَ عِنْدِي مِنْ الزَّكَاةِ وَلَيْسَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخُلْفُ وَلَا أَرَى حَبْسَ رَسُولِهِ إِلَّا مِنْ سَخْطَةٍ كَانَتْ فَانْطَلِقُوا فَنَأْتِيَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَلِيدَ بْنَ عُقْبَةَ ‏ ‏إِلَى ‏ ‏الْحَارِثِ ‏ ‏لِيَقْبِضَ مَا كَانَ عِنْدَهُ مِمَّا جَمَعَ مِنْ الزَّكَاةِ فَلَمَّا أَنْ سَارَ ‏ ‏الْوَلِيدُ ‏ ‏حَتَّى بَلَغَ بَعْضَ الطَّرِيقِ فَرِقَ فَرَجَعَ فَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏الْحَارِثَ ‏ ‏مَنَعَنِي الزَّكَاةَ وَأَرَادَ قَتْلِي فَضَرَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَعْثَ إِلَى ‏ ‏الْحَارِثِ ‏ ‏فَأَقْبَلَ ‏ ‏الْحَارِثُ ‏ ‏بِأَصْحَابِهِ إِذْ اسْتَقْبَلَ الْبَعْثَ وَفَصَلَ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏لَقِيَهُمْ ‏ ‏الْحَارِثُ ‏ ‏فَقَالُوا هَذَا ‏ ‏الْحَارِثُ ‏ ‏فَلَمَّا غَشِيَهُمْ قَالَ لَهُمْ إِلَى مَنْ بُعِثْتُمْ قَالُوا إِلَيْكَ قَالَ وَلِمَ قَالُوا إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ بَعَثَ إِلَيْكَ ‏ ‏الْوَلِيدَ بْنَ عُقْبَةَ ‏ ‏فَزَعَمَ أَنَّكَ مَنَعْتَهُ الزَّكَاةَ وَأَرَدْتَ قَتْلَهُ قَالَ لَا وَالَّذِي بَعَثَ ‏ ‏مُحَمَّدًا ‏ ‏بِالْحَقِّ مَا رَأَيْتُهُ بَتَّةً وَلَا أَتَانِي فَلَمَّا دَخَلَ ‏ ‏الْحَارِثُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنَعْتَ الزَّكَاةَ وَأَرَدْتَ قَتْلَ رَسُولِي قَالَ لَا وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا رَأَيْتُهُ وَلَا أَتَانِي وَمَا أَقْبَلْتُ إِلَّا حِينَ احْتَبَسَ عَلَيَّ رَسُولُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَشِيتُ أَنْ تَكُونَ كَانَتْ سَخْطَةً مِنْ اللَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ قَالَ فَنَزَلَتْ ‏ ‏الْحُجُرَاتُ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا إِنْ جَاءَكُمْ فَاسِقٌ بِنَبَإٍ فَتَبَيَّنُوا أَنْ تُصِيبُوا قَوْمًا بِجَهَالَةٍ فَتُصْبِحُوا عَلَى مَا فَعَلْتُمْ نَادِمِينَ ‏} ‏إِلَى هَذَا الْمَكَانِ ‏ { ‏فَضْلًا مِنْ اللَّهِ وَنِعْمَةً وَاللَّهُ عَلِيمٌ حَكِيمٌ ‏}","","",""],[17732,17732,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏قَالَ ‏ ‏أَتَى ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏فِي رَجُلٍ تَزَوَّجَ امْرَأَةً فَمَاتَ عَنْهَا وَلَمْ يَفْرِضْ لَهَا وَلَمْ يَدْخُلْ بِهَا فَسُئِلَ عَنْهَا شَهْرًا فَلَمْ يَقُلْ فِيهَا شَيْئًا ثُمَّ سَأَلُوهُ فَقَالَ أَقُولُ فِيهَا بِرَأْيِي فَإِنْ يَكُ خَطَأً فَمِنِّي وَمِنْ الشَّيْطَانِ وَإِنْ يَكُ صَوَابًا فَمِنْ اللَّهِ ‏ ‏لَهَا ‏ ‏صَدَقَةُ ‏ ‏إِحْدَى نِسَائِهَا وَلَهَا الْمِيرَاثُ وَعَلَيْهَا الْعِدَّةُ فَقَامَ ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏أَشْجَعَ ‏ ‏فَقَالَ أَشْهَدُ لَقَضَيْتَ فِيهَا بِقَضَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏بِرْوَعَ ابْنَةِ وَاشِقٍ ‏ ‏قَالَ فَقَالَ هَلُمَّ شَاهِدَاكَ فَشَهِدَ لَهُ ‏ ‏الْجَرَّاحُ ‏ ‏وَأَبُو سِنَانٍ ‏ ‏رَجُلَانِ مِنْ ‏ ‏أَشْجَعَ ‏","","",""],[17733,17733,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏وَالْأَسْوَدِ ‏ ‏قَالَ ‏ ‏أَتَى قَوْمٌ ‏ ‏عَبْدَ اللَّهِ يَعْنِي ابْنَ مَسْعُودٍ ‏ ‏فَقَالُوا مَا ‏ ‏تَرَى فِي رَجُلٍ تَزَوَّجَ امْرَأَةً ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ فَقَالَ رَجُلٌ مِنْ ‏ ‏أَشْجَعَ ‏ ‏قَالَ ‏ ‏مَنْصُورٌ ‏ ‏أُرَاهُ ‏ ‏سَلَمَةَ بْنَ يَزِيدَ ‏ ‏فَقَالَ فِي مِثْلِ هَذَا قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَزَوَّجَ ‏ ‏رَجُلٌ ‏ ‏مِنَّا امْرَأَةً مِنْ ‏ ‏بَنِي رُؤَاسٍ ‏ ‏يُقَالُ لَهَا ‏ ‏بِرْوَعُ بِنْتُ وَاشِقٍ ‏ ‏فَخَرَجَ مَخْرَجًا فَدَخَلَ فِي بِئْرٍ ‏ ‏فَأَسِنَ ‏ ‏فَمَاتَ وَلَمْ يَفْرِضْ لَهَا ‏ ‏صَدَاقًا ‏ ‏فَأَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏كَمَهْرِ نِسَائِهَا لَا ‏ ‏وَكْسَ ‏ ‏وَلَا ‏ ‏شَطَطَ ‏ ‏وَلَهَا الْمِيرَاثُ وَعَلَيْهَا الْعِدَّةُ ‏","","",""],[17734,17734,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏أَنَّ رَجُلًا تَزَوَّجَ امْرَأَةً فَتُوُفِّيَ ‏ ‏عَنْهَا زَوْجُهَا ‏ ‏قَبْلَ أَنْ يَدْخُلَ بِهَا وَلَمْ ‏ ‏يُسَمِّ ‏ ‏لَهَا ‏ ‏صَدَاقًا ‏ ‏فَسُئِلَ عَنْهَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَقَالَ ‏ ‏لَهَا ‏ ‏صَدَاقُ ‏ ‏إِحْدَى نِسَائِهَا وَلَا ‏ ‏وَكْسَ ‏ ‏وَلَا ‏ ‏شَطَطَ ‏ ‏وَلَهَا الْمِيرَاثُ وَعَلَيْهَا الْعِدَّةُ فَقَامَ ‏ ‏أَبُو سِنَانٍ الْأَشْجَعِيُّ ‏ ‏فِي ‏ ‏رَهْطٍ ‏ ‏مِنْ ‏ ‏أَشْجَعَ ‏ ‏فَقَالُوا نَشْهَدُ لَقَدْ قَضَيْتَ فِيهَا بِقَضَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏بِرْوَعَ بِنْتِ وَاشِقٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَحَدَّثَنَا ‏ ‏ابْنُ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏بِهَذَا ‏ ‏و حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَاه ‏ ‏ابْنُ أَبِي شَيْبَةَ عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[17735,17735,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏فِي رَجُلٍ تَزَوَّجَ امْرَأَةً فَمَاتَ عَنْهَا وَلَمْ يَدْخُلْ بِهَا وَلَمْ ‏ ‏يَفْرِضْ ‏ ‏لَهَا قَالَ ‏ ‏لَهَا ‏ ‏الصَّدَاقُ ‏ ‏وَعَلَيْهَا الْعِدَّةُ وَلَهَا الْمِيرَاثُ فَقَالَ ‏ ‏مَعْقِلُ بْنُ سِنَانٍ ‏ ‏شَهِدْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى بِهِ فِي ‏ ‏بِرْوَعَ بِنْتِ وَاشِقٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏فِرَاسٍ ‏","","",""],[17736,17736,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏أُتِيَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فِي امْرَأَةٍ تَزَوَّجَهَا رَجُلٌ فَتُوُفِّيَ وَلَمْ ‏ ‏يَفْرِضْ ‏ ‏لَهَا ‏ ‏صَدَاقًا ‏ ‏وَلَمْ يَكُنْ دَخَلَ بِهَا قَالَ فَاخْتَلَفُوا إِلَيْهِ فَقَالَ أَرَى ‏ ‏لَهَا مِثْلُ ‏ ‏صَدَاقِ ‏ ‏نِسَائِهَا وَلَهَا الْمِيرَاثُ وَعَلَيْهَا الْعِدَّةُ فَشَهِدَ ‏ ‏مَعْقِلُ بْنُ سِنَانٍ الْأَشْجَعِيُّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى فِي ‏ ‏بِرْوَعَ بِنْتِ وَاشِقٍ ‏ ‏بِمِثْلِ هَذَا ‏","","",""],[17737,17737,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي غَرَزَةَ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نَبْتَاعُ ‏ ‏الْأَوْسَاقَ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَكُنَّا ‏ ‏نُسَمِّي أَنْفُسَنَا ‏ ‏السَّمَاسِرَةَ ‏ ‏فَأَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمَّانَا بِاسْمٍ أَحْسَنَ مِمَّا كُنَّا ‏ ‏نُسَمِّي أَنْفُسَنَا بِهِ فَقَالَ يَا مَعْشَرَ التُّجَّارِ ‏ ‏إِنَّ هَذَا الْبَيْعَ يَحْضُرُهُ ‏ ‏اللَّغْوُ ‏ ‏وَالْحَلِفُ فَشُوبُوهُ ‏ ‏بِالصَّدَقَةِ ‏","","",""],[17738,17738,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏وَإِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏أَنَا النَّبِيُّ لَا ‏ ‏كَذِبْ ‏ ‏أَنَا ‏ ‏ابْنُ عَبْدِ الْمُطَّلِبْ ‏","","",""],[17739,17739,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏قَالَ فَحَدَّثَنِي ‏ ‏بِهِ ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏قَالَ فَحَدَّثَ أَنَّ ‏ ‏الْبَرَاءَ بْنَ عَازِبٍ ‏ ‏قَالَ ‏ ‏كَانَتْ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى فَرَكَعَ وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ وَإِذَا سَجَدَ وَإِذَا رَفَعَ رَأْسَهُ مِنْ السُّجُودِ وَبَيْنَ السَّجْدَتَيْنِ قَرِيبًا مِنْ السَّوَاءِ ‏","","",""],[17740,17740,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي لَيْلَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْبَرَاءُ بْنُ عَازِبٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْنُتُ ‏ ‏فِي صَلَاةِ الصُّبْحِ وَالْمَغْرِبِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏لَيْسَ يُرْوَى عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏قَنَتَ ‏ ‏فِي الْمَغْرِبِ إِلَّا فِي هَذَا الْحَدِيثِ وَعَنْ ‏ ‏عَلِيٍّ ‏ ‏قَوْلُهُ ‏","","",""],[17741,17741,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ الْهَمْدَانِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏الْبَرَاءَ بْنَ عَازِبٍ ‏ ‏يَقُولُ ‏ ‏لَمَّا أَقْبَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏مَكَّةَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ فَتَبِعَهُ ‏ ‏سُرَاقَةُ بْنُ مَالِكِ بْنِ جُعْشُمٍ ‏ ‏فَدَعَا عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَاخَتْ ‏ ‏بِهِ فَرَسُهُ فَقَالَ ادْعُ اللَّهَ لِي وَلَا أَضُرُّكَ قَالَ فَدَعَا اللَّهَ لَهُ قَالَ فَعَطِشَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرُّوا بِرَاعِي غَنَمٍ ‏ ‏فَقَالَ ‏ ‏أَبُو بَكْرٍ الصِّدِّيقُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَأَخَذْتُ قَدَحًا فَحَلَبْتُ فِيهِ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُثْبَةً ‏ ‏مِنْ لَبَنٍ فَأَتَيْتُهُ بِهِ فَشَرِبَ حَتَّى رَضِيتُ ‏","","",""],[17742,17742,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏وَرَجُلٍ ‏ ‏آخَرَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَنَامَ تَوَسَّدَ يَمِينَهُ وَيَقُولُ اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَجْمَعُ عِبَادَكَ ‏ ‏قَالَ فَقَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏وَقَالَ الْآخَرُ يَوْمَ تَبْعَثُ عِبَادَكَ ‏","","",""],[17743,17743,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْبَرَاءَ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا ‏ ‏مَرْبُوعًا ‏ ‏بَعِيدَ مَا بَيْنَ الْمَنْكِبَيْنِ عَظِيمَ ‏ ‏الْجُمَّةِ ‏ ‏إِلَى ‏ ‏شَحْمَةِ ‏ ‏أُذُنَيْهِ عَلَيْهِ ‏ ‏حُلَّةٌ ‏ ‏حَمْرَاءُ مَا رَأَيْتُ شَيْئًا قَطُّ أَحْسَنَ مِنْهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[17744,17744,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْبَرَاءَ ‏ ‏يَقُولُ ‏ ‏قَرَأَ ‏ ‏رَجُلٌ ‏ ‏الْكَهْفَ ‏ ‏وَفِي الدَّارِ دَابَّةٌ فَجَعَلَتْ ‏ ‏تَنْفِرُ ‏ ‏فَنَظَرَ فَإِذَا ضَبَابَةٌ ‏ ‏أَوْ سَحَابَةٌ ‏ ‏قَدْ غَشِيَتْهُ قَالَا فَذَكَرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ اقْرَأْ فُلَانُ ‏ ‏فَإِنَّهَا ‏ ‏السَّكِينَةُ ‏ ‏تَنَزَّلَتْ عِنْدَ الْقُرْآنِ ‏ ‏أَوْ تَنَزَّلَتْ لِلْقُرْآنِ ‏","","",""],[17745,17745,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏الْبَرَاءَ ‏ ‏وَسَأَلَهُ رَجُلٌ مِنْ ‏ ‏قَيْسٍ ‏ ‏فَقَالَ أَفَرَرْتُمْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فَقَالَ ‏ ‏الْبَرَاءُ ‏ ‏وَلَكِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَفِرَّ كَانَتْ ‏ ‏هَوَازِنُ ‏ ‏نَاسًا رُمَاةً وَإِنَّا لَمَّا حَمَلْنَا عَلَيْهِمْ انْكَشَفُوا ‏ ‏فَأَكْبَبْنَا ‏ ‏عَلَى الْغَنَائِمِ فَاسْتَقْبَلُونَا بِالسِّهَامِ وَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى بَغْلَتِهِ الْبَيْضَاءِ وَإِنَّ ‏ ‏أَبَا سُفْيَانَ بْنَ الْحَارِثِ ‏ ‏آخِذٌ بِلِجَامِهَا وَهُوَ يَقُولُ ‏ ‏أَنَا النَّبِيُّ لَا ‏ ‏كَذِبْ ‏ ‏أَنَا ‏ ‏ابْنُ عَبْدِ الْمُطَّلِبْ ‏","","",""],[17746,17746,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَبِيعَ بْنَ الْبَرَاءِ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الْبَرَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَقْبَلَ مِنْ سَفَرٍ قَالَ آيِبُونَ تَائِبُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ ‏","","",""],[17747,17747,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِلْبَرَاءِ ‏ ‏الرَّجُلُ يَحْمِلُ عَلَى الْمُشْرِكِينَ أَهُوَ مِمَّنْ أَلْقَى بِيَدِهِ إِلَى التَّهْلُكَةِ قَالَ لَا لِأَنَّ اللَّهَ عَزَّ وَجَلَّ بَعَثَ رَسُولَهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ { ‏فَقَاتِلْ فِي سَبِيلِ اللَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ ‏} ‏إِنَّمَا ذَاكَ فِي النَّفَقَةِ ‏","","",""],[17748,17748,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِلْبَرَاءِ ‏ ‏أَكَانَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيدًا هَكَذَا مِثْلَ السَّيْفِ قَالَ لَا بَلْ كَانَ مِثْلَ الْقَمَرِ ‏","","",""],[17749,17749,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَنَزَلْنَا بِغَدِيرِ خُمٍّ فَنُودِيَ فِينَا الصَّلَاةُ جَامِعَةٌ وَكُسِحَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَحْتَ شَجَرَتَيْنِ فَصَلَّى الظُّهْرَ وَأَخَذَ بِيَدِ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقَالَ أَلَسْتُمْ تَعْلَمُونَ أَنِّي أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ قَالُوا بَلَى قَالَ أَلَسْتُمْ تَعْلَمُونَ أَنِّي أَوْلَى بِكُلِّ مُؤْمِنٍ مِنْ نَفْسِهِ قَالُوا بَلَى قَالَ فَأَخَذَ بِيَدِ ‏ ‏عَلِيٍّ ‏ ‏فَقَالَ ‏ ‏مَنْ كُنْتُ مَوْلَاهُ ‏ ‏فَعَلِيٌّ ‏ ‏مَوْلَاهُ اللَّهُمَّ وَالِ مَنْ وَالَاهُ وَعَادِ مَنْ عَادَاهُ ‏ ‏قَالَ ‏ ‏فَلَقِيَهُ ‏ ‏عُمَرُ ‏ ‏بَعْدَ ذَلِكَ فَقَالَ ‏ ‏هَنِيئًا يَا ‏ ‏ابْنَ أَبِي طَالِبٍ ‏ ‏أَصْبَحْتَ وَأَمْسَيْتَ مَوْلَى كُلِّ مُؤْمِنٍ وَمُؤْمِنَةٍ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏هُدْبَةُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[17750,17750,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏زُبَيْدٌ ‏ ‏أَخْبَرَنِي ‏ ‏مَنْصُورٌ ‏ ‏وَدَاوُدُ ‏ ‏وَابْنُ عَوْنٍ ‏ ‏وَمُجَالِدٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏وَهَذَا حَدِيثُ ‏ ‏زُبَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الْبَرَاءِ ‏ ‏وَحَدَّثَنَا ‏ ‏عِنْدَ سَارِيَةٍ فِي الْمَسْجِدِ قَالَ وَلَوْ كُنْتُ ثَمَّ لَأَخْبَرْتُكُمْ بِمَوْضِعِهَا ‏ ‏قَالَ ‏ ‏خَطَبَنَا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ أَوَّلَ مَا نَبْدَأُ بِهِ فِي يَوْمِنَا هَذَا أَنْ نُصَلِّيَ ثُمَّ نَرْجِعَ فَنَنْحَرَ فَمَنْ فَعَلَ ذَلِكَ فَقَدْ أَصَابَ سُنَّتَنَا وَمَنْ ذَبَحَ قَبْلَ ذَلِكَ فَإِنَّمَا هُوَ لَحْمٌ قَدَّمَهُ لِأَهْلِهِ لَيْسَ مِنْ ‏ ‏النُّسُكِ ‏ ‏فِي شَيْءٍ قَالَ وَذَبَحَ خَالِي ‏ ‏أَبُو بُرْدَةَ بْنُ نِيَارٍ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ ‏ ‏ذَبَحْتُ وَعِنْدِي ‏ ‏جَذَعَةٌ ‏ ‏خَيْرٌ مِنْ ‏ ‏مُسِنَّةٍ ‏ ‏قَالَ اجْعَلْهَا مَكَانَهَا وَلَمْ تُجْزِئْ أَوْ تُوفِ عَنْ أَحَدٍ بَعْدَكَ ‏","","",""],[17751,17751,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَلْقَمَةُ بْنُ مَرْثَدٍ ‏ ‏قَالَ أَخْبَرَنِي عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي الْقَبْرِ إِذَا سُئِلَ فَعَرَفَ رَبَّهُ قَالَ ‏ ‏وَقَالَ شَيْءٌ لَا أَحْفَظُهُ ‏ ‏فَذَلِكَ قَوْلُهُ عَزَّ وَجَلَّ ‏ { ‏يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ ‏}","","",""],[17752,17752,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَلَمْ يَسْمَعْهُ مِنْ ‏ ‏الْبَرَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِنَاسٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ ‏ ‏إِنْ كُنْتُمْ لَا بُدَّ فَاعِلِينَ فَأَفْشُوا السَّلَامَ وَأَعِينُوا الْمَظْلُومَ وَاهْدُوا السَّبِيلَ ‏","","",""],[17753,17753,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى مَجْلِسٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ ‏ ‏إِنْ أَبَيْتُمْ إِلَّا أَنْ تَجْلِسُوا فَاهْدُوا السَّبِيلَ وَرُدُّوا السَّلَامَ وَأَعِينُوا الْمَظْلُومَ ‏","","",""],[17754,17754,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏الْبَرَاءَ ‏ ‏يَقُولُ فِي هَذِهِ الْآيَةِ ‏ ‏لَا يَسْتَوِي الْقَاعِدُونَ مِنْ الْمُؤْمِنِينَ وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ قَالَ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَيْدًا ‏ ‏فَجَاءَ بِكَتِفٍ فَكَتَبَهَا قَالَ فَشَكَا إِلَيْهِ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏ ‏ضَرَارَتَهُ فَنَزَلَتْ ‏ { ‏لَا يَسْتَوِي الْقَاعِدُونَ مِنْ الْمُؤْمِنِينَ غَيْرُ ‏ ‏أُولِي ‏ ‏الضَّرَرِ ‏}","","",""],[17755,17755,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي زَائِدَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ ‏ ‏لِلْبَرَاءِ ‏ ‏وَهُوَ يَمْزَحُ مَعَهُ قَدْ فَرَرْتُمْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنْتُمْ أَصْحَابُهُ قَالَ ‏ ‏الْبَرَاءُ ‏ ‏إِنِّي لَأَشْهَدُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا فَرَّ يَوْمَئِذٍ وَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ حُفِرَ ‏ ‏الْخَنْدَقُ ‏ ‏وَهُوَ ‏ ‏يَنْقُلُ مَعَ النَّاسِ التُّرَابَ وَهُوَ يَتَمَثَّلُ كَلِمَةَ ‏ ‏ابْنِ رَوَاحَةَ ‏ ‏اللَّهُمَّ لَوْلَا أَنْتَ مَا اهْتَدَيْنَا ‏ ‏وَلَا تَصَدَّقْنَا وَلَا صَلَّيْنَا ‏ ‏فَأَنْزِلَنْ ‏ ‏سَكِينَةً ‏ ‏عَلَيْنَا ‏ ‏وَثَبِّتْ الْأَقْدَامَ إِنْ لَاقَيْنَا ‏ ‏فَإِنَّ الْأُلَى قَدْ بَغَوْا عَلَيْنَا ‏ ‏وَإِنْ أَرَادُوا فِتْنَةً أَبَيْنَا ‏ ‏يَمُدُّ بِهَا صَوْتَهُ ‏","","",""],[17756,17756,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ افْتَتَحَ الصَّلَاةَ رَفَعَ يَدَيْهِ ‏","","",""],[17757,17757,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ الْحَقِّ عَلَى الْمُسْلِمِينَ أَنْ يَغْتَسِلَ أَحَدُهُمْ يَوْمَ الْجُمُعَةِ وَأَنْ يَمَسَّ مِنْ طِيبٍ إِنْ كَانَ عِنْدَ أَهْلِهِ فَإِنْ لَمْ يَكُنْ عِنْدَهُمْ طِيبٌ فَإِنَّ الْمَاءَ أَطْيَبُ ‏","","",""],[17758,17758,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو جَنَابٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْبَرَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏فَقَالَ إِنَّ أَوَّلَ ‏ ‏نُسُكِكُمْ ‏ ‏هَذِهِ الصَّلَاةُ فَقَامَ إِلَيْهِ ‏ ‏أَبُو بُرْدَةَ بْنُ نِيَارٍ ‏ ‏خَالِي ‏ ‏قَالَ ‏ ‏سُهَيْلٌ ‏ ‏وَكَانَ بَدْرِيًّا ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ كَانَ يَوْمًا ‏ ‏نَشْتَهِي فِيهِ اللَّحْمَ ثُمَّ ‏ ‏إِنَّا عَجَّلْنَا فَذَبَحْنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَبْدِلْهَا قَالَ يَا رَسُولَ اللَّهِ إِنَّ عِنْدَنَا مَاعِزًا ‏ ‏جَذَعًا ‏ ‏قَالَ فَهِيَ لَكَ وَلَيْسَ لِأَحَدٍ بَعْدَكَ ‏","","",""],[17759,17759,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَنَابٍ الْكَلْبِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَزيدُ بْنُ الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا فِي الْمُصَلَّى يَوْمَ أَضْحَى فَأَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمَ عَلَى النَّاسِ ثُمَّ قَالَ إِنَّ أَوَّلَ ‏ ‏نُسُكِ ‏ ‏يَوْمِكُمْ هَذَا الصَّلَاةُ قَالَ فَتَقَدَّمَ فَصَلَّى رَكْعَتَيْنِ ثُمَّ سَلَّمَ ثُمَّ اسْتَقْبَلَ النَّاسَ بِوَجْهِهِ وَأُعْطِيَ قَوْسًا ‏ ‏أَوْ عَصًا ‏ ‏فَاتَّكَأَ عَلَيْهِ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ وَأَمَرَهُمْ وَنَهَاهُمْ وَقَالَ ‏ ‏مَنْ كَانَ مِنْكُمْ عَجَّلَ ذَبْحًا فَإِنَّمَا هِيَ جَزْرَةٌ أَطْعَمَهُ أَهْلَهُ إِنَّمَا الذَّبْحُ بَعْدَ الصَّلَاةِ فَقَامَ إِلَيْهِ خَالِي ‏ ‏أَبُو بُرْدَةَ بْنُ نِيَارٍ ‏ ‏فَقَالَ أَنَا عَجَّلْتُ ذَبْحَ شَاتِي يَا رَسُولَ اللَّهِ لِيُصْنَعَ لَنَا طَعَامٌ نَجْتَمِعُ عَلَيْهِ إِذَا رَجَعْنَا وَعِنْدِي ‏ ‏جَذَعَةٌ ‏ ‏مِنْ مَعْزٍ هِيَ أَوْفَى مِنْ الَّذِي ذَبَحْتُ ‏ ‏أَفَتُغْنِي عَنِّي يَا رَسُولَ اللَّهِ قَالَ نَعَمْ وَلَنْ تُغْنِيَ عَنْ أَحَدٍ بَعْدَكَ قَالَ ثُمَّ قَالَ يَا ‏ ‏بِلَالُ ‏ ‏قَالَ فَمَشَى وَاتَّبَعَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى أَتَى النِّسَاءَ فَقَالَ يَا مَعْشَرَ النِّسْوَانِ ‏ ‏تَصَدَّقْنَ ‏ ‏الصَّدَقَةُ ‏ ‏خَيْرٌ لَكُنَّ قَالَ فَمَا رَأَيْتُ يَوْمًا قَطُّ أَكْثَرَ خَدَمَةً مَقْطُوعَةً ‏ ‏وَقِلَادَةً ‏ ‏وَقُرْطًا ‏ ‏مِنْ ذَلِكَ الْيَوْمِ ‏","","",""],[17760,17760,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ إِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِيَادُ بْنُ لَقِيطٍ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَجَدْتَ فَضَعْ كَفَّيْكَ وَارْفَعْ مِرْفَقَيْكَ ‏","","",""],[17761,17761,"","","‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏حَدَّثَنَاه ‏ ‏جَعْفَرُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ إِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِيَادٌ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ تَقُولُونَ بِفَرَحِ رَجُلٍ انْفَلَتَتْ مِنْهُ رَاحِلَتُهُ تَجُرُّ زِمَامَهَا بِأَرْضٍ قَفْرٍ لَيْسَ فِيهَا طَعَامٌ وَلَا شَرَابٌ وَعَلَيْهَا طَعَامٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَشَرَابٌ ‏ ‏فَطَلَبَهَا حَتَّى شَقَّ عَلَيْهِ ثُمَّ مَرَّتْ ‏ ‏بِجِذْلِ ‏ ‏شَجَرَةٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏بِجِذْلٍ ‏ ‏فَتَعَلَّقَ زِمَامُهَا فَوَجَدَهَا مُعَلَّقَةً بِهِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏مُتَعَلِّقَةً بِهِ ‏ ‏قَالَ قُلْنَا شَدِيدٌ يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا وَاللَّهِ ‏ ‏لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ مِنْ الرَّجُلِ بِرَاحِلَتِهِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏و حَدَّثَنَاه ‏ ‏جَعْفَرُ بْنُ حُمَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ إِيَادٍ ‏ ‏مِثْلَهُ ‏","","",""],[17762,17762,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ ‏ ‏مَا كُلُّ الْحَدِيثِ سَمِعْنَاهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُحَدِّثُنَا أَصْحَابُنَا عَنْهُ كَانَتْ تَشْغَلُنَا عَنْهُ رَعِيَّةُ الْإِبِلِ ‏","","",""],[17763,17763,"","","‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْسَجَةَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَيِّنُوا الْقُرْآنَ بِأَصْوَاتِكُمْ ‏","","",""],[17764,17764,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مِنْ الْحَقِّ عَلَى الْمُسْلِمِينَ يَوْمَ الْجُمُعَةِ أَنْ يَغْتَسِلَ وَيَمَسَّ طِيبًا إِنْ وَجَدَ فَإِنْ لَمْ يَجِدْ طِيبًا فَالْمَاءُ طِيبٌ ‏","","",""],[17765,17765,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ أَوَّلَ مَا قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏نَزَلَ عَلَى أَجْدَادِهِ وَأَخْوَالِهِ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَأَنَّهُ صَلَّى قِبَلَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏سِتَّةَ عَشَرَ ‏ ‏أَوْ سَبْعَةَ عَشَرَ ‏ ‏شَهْرًا وَكَانَ يُعْجِبُهُ أَنْ تَكُونَ قِبْلَتُهُ قِبَلَ ‏ ‏الْبَيْتِ ‏ ‏وَأَنَّهُ صَلَّى أَوَّلَ صَلَاةٍ صَلَّاهَا صَلَاةَ الْعَصْرِ وَصَلَّى مَعَهُ قَوْمٌ فَخَرَجَ رَجُلٌ مِمَّنْ صَلَّى مَعَهُ فَمَرَّ عَلَى أَهْلِ مَسْجِدٍ وَهُمْ رَاكِعُونَ فَقَالَ أَشْهَدُ بِاللَّهِ لَقَدْ صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِبَلَ ‏ ‏مَكَّةَ ‏ ‏قَالَ فَدَارُوا كَمَا هُمْ قِبَلَ ‏ ‏الْبَيْتِ ‏ ‏وَكَانَ يُعْجِبُهُ أَنْ ‏ ‏يُحَوَّلَ ‏ ‏قِبَلَ ‏ ‏الْبَيْتِ ‏ ‏وَكَانَ ‏ ‏الْيَهُودُ ‏ ‏قَدْ أَعْجَبَهُمْ إِذْ كَانَ ‏ ‏يُصَلِّي قِبَلَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏وَأَهْلُ الْكِتَابِ ‏ ‏فَلَمَّا وَلَّى وَجْهَهُ قِبَلَ ‏ ‏الْبَيْتِ ‏ ‏أَنْكَرُوا ذَلِكَ ‏","","",""],[17766,17766,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ابْنِهِ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَمَاتَ وَهُوَ ابْنُ سِتَّةَ عَشَرَ شَهْرًا وَقَالَ إِنَّ لَهُ فِي الْجَنَّةِ مَنْ يُتِمُّ رَضَاعَهُ وَهُوَ صِدِّيقٌ ‏","","",""],[17767,17767,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ ‏ ‏مَا كُلُّ مَا نُحَدِّثُكُمُوهُ سَمِعْنَاهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِنْ حَدَّثَنَا أَصْحَابُنَا وَكَانَتْ تَشْغَلُنَا رَعِيَّةُ الْإِبِلِ ‏","","",""],[17768,17768,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏أَوْ غَيْرِهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏بِالْعَبَّاسِ ‏ ‏قَدْ أَسَرَهُ فَقَالَ ‏ ‏الْعَبَّاسُ ‏ ‏يَا رَسُولَ اللَّهِ لَيْسَ هَذَا أَسَرَنِي أَسَرَنِي رَجُلٌ مِنْ الْقَوْمِ أَنْزِعُ مِنْ هَيْئَتِهِ كَذَا وَكَذَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلرَّجُلِ ‏ ‏لَقَدْ آزَرَكَ اللَّهُ بِمَلَكٍ كَرِيمٍ ‏","","",""],[17769,17769,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْبَرَاءَ بْنَ عَازِبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُحِبُّ ‏ ‏الْأَنْصَارَ ‏ ‏إِلَّا مُؤْمِنٌ وَلَا يُبْغِضُهُمْ إِلَّا مُنَافِقٌ مَنْ أَحَبَّهُمْ أَحَبَّهُ اللَّهُ وَمَنْ أَبْغَضَهُمْ أَبْغَضَهُ اللَّهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قُلْتُ ‏ ‏لِعَدِيٍّ ‏ ‏أَنْتَ سَمِعْتَ مِنْ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ إِيَّايَ يُحَدِّثُ ‏","","",""],[17770,17770,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ حَامِلًا ‏ ‏الْحَسَنَ ‏ ‏فَقَالَ إِنِّي أُحِبُّهُ فَأَحِبَّهُ ‏","","",""],[17771,17771,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏مُرْضِعٌ فِي الْجَنَّةِ ‏","","",""],[17772,17772,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي سَفَرٍ فَقَرَأَ فِي الْعِشَاءِ الْآخِرَةِ فِي إِحْدَى الرَّكْعَتَيْنِ ‏ ‏بِالتِّينِ وَالزَّيْتُونِ ‏","","",""],[17773,17773,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَشْعَثُ بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ سُوَيْدِ بْنِ مُقَرِّنٍ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَبْعٍ وَنَهَانَا عَنْ سَبْعٍ قَالَ ‏ ‏فَذَكَرَ مَا أَمَرَهُمْ مِنْ ‏ ‏عِيَادَةِ ‏ ‏الْمَرِيضِ وَاتِّبَاعِ الْجَنَائِزِ ‏ ‏وَتَشْمِيتِ ‏ ‏الْعَاطِسِ وَرَدِّ السَّلَامِ ‏ ‏وَإِبْرَارِ ‏ ‏الْمُقْسِمِ وَإِجَابَةِ الدَّاعِي وَنَصْرِ الْمَظْلُومِ وَنَهَانَا عَنْ آنِيَةِ الْفِضَّةِ وَعَنْ خَاتَمِ الذَّهَبِ ‏ ‏أَوْ قَالَ حَلْقَةِ الذَّهَبِ ‏ ‏وَالْإِسْتَبْرَقِ ‏ ‏وَالْحَرِيرِ ‏ ‏وَالدِّيبَاجِ ‏ ‏وَالْمِيثَرَةِ ‏ ‏وَالْقَسِّيِّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَشْعَثِ بْنِ سُلَيْمٍ ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ ‏ ‏تَشْمِيتِ ‏ ‏الْعَاطِسِ ‏","","",""],[17774,17774,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ الْكُوفِيِّ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الصَّفِّ الْمُقَدَّمِ وَالْمُؤَذِّنُ يُغْفَرُ لَهُ مَدَّ صَوْتِهِ وَيُصَدِّقُهُ مَنْ سَمِعَهُ مِنْ رَطْبٍ وَيَابِسٍ وَلَهُ مِثْلُ أَجْرِ مَنْ صَلَّى مَعَهُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏و حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ الْقَوَارِيرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏فَذَكَرَ مِثْلَهُ بِإِسْنَادِهِ ‏","","",""],[17775,17775,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ ‏لَا يَسْتَوِي الْقَاعِدُونَ مِنْ الْمُؤْمِنِينَ وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ دَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَيْدًا ‏ ‏فَجَاءَ بِكَتِفٍ فَكَتَبَهَا قَالَ فَجَاءَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏ ‏فَشَكَا ضَرَارَتَهُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَزَلَتْ ‏ { ‏غَيْرُ ‏ ‏أُولِي ‏ ‏الضَّرَرِ ‏}","","",""],[17776,17776,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْبَرَاءَ ‏ ‏قَالَ ‏ ‏قَرَأَ ‏ ‏رَجُلٌ ‏ ‏سُورَةَ ‏ ‏الْكَهْفِ ‏ ‏وَلَهُ دَابَّةٌ مَرْبُوطَةٌ فَجَعَلَتْ الدَّابَّةُ تَنْفِرُ فَنَظَرَ الرَّجُلُ إِلَى سَحَابَةٍ قَدْ غَشِيَتْهُ ‏ ‏أَوْ ضَبَابَةٍ ‏ ‏فَفَزِعَ فَذَهَبَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ سَمَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاكَ الرَّجُلَ قَالَ نَعَمْ فَقَالَ اقْرَأْ فُلَانُ فَإِنَّ ‏ ‏السَّكِينَةَ ‏ ‏نَزَلَتْ لِلْقُرْآنِ ‏ ‏أَوْ عِنْدَ الْقُرْآنِ ‏","","",""],[17777,17777,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏سُلَيْمَانُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُبَيْدَ بْنَ فَيْرُوزَ ‏ ‏مَوْلَى ‏ ‏بَنِي شَيْبَانَ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏الْبَرَاءَ ‏ ‏عَنْ الْأَضَاحِيِّ مَا نَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا كَرِهَ فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيَدِي أَقْصَرُ مِنْ يَدِهِ فَقَالَ ‏ ‏أَرْبَعٌ لَا تُجْزِئُ الْعَوْرَاءُ الْبَيِّنُ عَوَرُهَا وَالْمَرِيضَةُ الْبَيِّنُ مَرَضُهَا وَالْعَرْجَاءُ الْبَيِّنُ ‏ ‏ظَلْعُهَا ‏ ‏وَالْكَسِيرُ الَّتِي لَا تُنْقِي قَالَ قُلْتُ فَإِنِّي أَكْرَهُ أَنْ يَكُونَ فِي الْقَرْنِ نَقْصٌ ‏ ‏أَوْ قَالَ فِي الْأُذُنِ نَقْصٌ ‏ ‏أَوْ فِي السِّنِّ نَقْصٌ ‏ ‏قَالَ مَا كَرِهْتَ فَدَعْهُ وَلَا تُحَرِّمْهُ عَلَى أَحَدٍ ‏","","",""],[17778,17778,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ الْأَنْصَارِيَّ ‏ ‏يَخْطُبُ ‏ ‏فَقَالَ أَنَا ‏ ‏الْبَرَاءُ ‏ ‏وَهُوَ غَيْرُ كَذُوبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَامُوا قِيَامًا حَتَّى يَسْجُدَ ثُمَّ يَسْجُدُونَ ‏","","",""],[17779,17779,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْبَرَاءَ بْنَ عَازِبٍ ‏ ‏قَالَ ‏ ‏أَوَّلُ مَنْ قَدِمَ عَلَيْنَا مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُصْعَبُ بْنُ عُمَيْرٍ ‏ ‏وَابْنُ أُمِّ مَكْتُومٍ ‏ ‏قَالَ فَجَعَلَا يُقْرِئَانِ النَّاسَ الْقُرْآنَ ثُمَّ جَاءَ ‏ ‏عَمَّارٌ ‏ ‏وَبِلَالٌ ‏ ‏وَسَعْدٌ ‏ ‏قَالَ ثُمَّ جَاءَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏فِي عِشْرِينَ ثُمَّ ‏ ‏جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا رَأَيْتُ أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏فَرِحُوا بِشَيْءٍ قَطُّ فَرَحَهُمْ بِهِ حَتَّى رَأَيْتُ الْوَلَائِدَ وَالصِّبْيَانَ يَقُولُونَ هَذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ جَاءَ قَالَ فَمَا قَدِمَ حَتَّى قَرَأْتُ ‏ ‏سَبِّحْ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏فِي سُوَرٍ مِنْ ‏ ‏الْمُفَصَّلِ ‏","","",""],[17780,17780,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْبَرَاءَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْقُلُ مَعَنَا التُّرَابَ يَوْمَ الْأَحْزَابِ وَيَقُولُ ‏ ‏اللَّهُمَّ لَوْلَا أَنْتَ مَا اهْتَدَيْنَا ‏ ‏وَلَا تَصَدَّقْنَا وَلَا صَلَّيْنَا ‏ ‏فَأَنْزِلَنْ ‏ ‏سَكِينَةً ‏ ‏عَلَيْنَا ‏ ‏إِنَّ ‏ ‏الْأُلَى ‏ ‏قَدْ بَغَوْا عَلَيْنَا ‏ ‏وَإِذَا أَرَادُوا فِتْنَةً أَبَيْنَا ‏ ‏يَمُدُّ بِهَا صَوْتَهُ ‏","","",""],[17781,17781,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏الْحَكَمُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا رَكَعَ وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ وَسُجُودُهُ وَمَا بَيْنَ السَّجْدَتَيْنِ قَرِيبًا مِنْ السَّوَاءِ ‏","","",""],[17782,17782,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْبَرَاءَ بْنَ عَازِبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَنْ ‏ ‏يَقُولَ إِذَا أَخَذَ مَضْجَعَهُ اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ وَوَجَّهْتُ وَجْهِي إِلَيْكَ وَفَوَّضْتُ أَمْرِي إِلَيْكَ وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ رَغْبَةً وَرَهْبَةً إِلَيْكَ لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ وَنَبِيِّكَ الَّذِي أَرْسَلْتَ فَإِنْ مَاتَ مَاتَ عَلَى الْفِطْرَةِ ‏","","",""],[17783,17783,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ مُصَرِّفٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْسَجَةَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَنَحَ مِنْحَةَ وَرِقٍ أَوْ مِنْحَةَ لَبَنٍ أَوْ هَدَى ‏ ‏زُقَاقًا ‏ ‏فَهُوَ كَعِتَاقِ نَسَمَةٍ وَمَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ فَهُوَ كَعِتَاقِ نَسَمَةٍ ‏","","",""],[17784,17784,"","","‏ ‏قَالَ وَكَانَ يَأْتِي نَاحِيَةَ الصَّفِّ إِلَى نَاحِيَتِهِ يُسَوِّي صُدُورَهُمْ وَمَنَاكِبَهُمْ يَقُولُ ‏ ‏لَا تَخْتَلِفُوا فَتَخْتَلِفَ قُلُوبُكُمْ قَالَ إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الصُّفُوفِ الْأُوَلِ وَكَانَ يَقُولُ زَيِّنُوا الْقُرْآنَ بِأَصْوَاتِكُمْ ‏","","",""],[17785,17785,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏أَنْبَأَنِي قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ ‏ ‏يَخْطُبُ ‏ ‏حَدَّثَنَا ‏ ‏الْبَرَاءُ ‏ ‏وَكَانَ غَيْرَ كَذُوبٍ ‏ ‏أَنَّهُمْ كَانُوا ‏ ‏إِذَا صَلَّوْا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَامُوا قِيَامًا حَتَّى يَرَوْهُ قَدْ سَجَدَ فَيَسْجُدُوا ‏","","",""],[17786,17786,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏طَلْحَةُ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْسَجَةَ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَنَحَ مِنْحَةَ وَرِقٍ أَوْ مَنَحَ وَرِقًا أَوْ ‏ ‏هَدَى ‏ ‏زُقَاقًا ‏ ‏أَوْ سَقَى لَبَنًا كَانَ لَهُ عَدْلَ رَقَبَةٍ أَوْ ‏ ‏نَسَمَةٍ ‏ ‏وَمَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ عَشْرَ مَرَّاتٍ كَانَ لَهُ كَعَدْلِ رَقَبَةٍ أَوْ ‏ ‏نَسَمَةٍ ‏","","",""],[17787,17787,"","","‏ ‏قَالَ وَكَانَ يَأْتِينَا إِذَا قُمْنَا إِلَى الصَّلَاةِ فَيَمْسَحُ ‏ ‏عَوَاتِقَنَا ‏ ‏أَوْ صُدُورَنَا وَكَانَ يَقُولُ ‏ ‏لَا تَخْتَلِفُوا فَتَخْتَلِفَ قُلُوبُكُمْ وَكَانَ يَقُولُ إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الصَّفِّ الْأَوَّلِ ‏ ‏أَوْ الصُّفُوفِ الْأُوَلِ ‏","","",""],[17788,17788,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَالِحُ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَمَّى ‏ ‏الْمَدِينَةَ ‏ ‏يَثْرِبَ ‏ ‏فَلْيَسْتَغْفِرْ اللَّهَ عَزَّ وَجَلَّ هِيَ طَابَةُ هِيَ طَابَةُ ‏","","",""],[17789,17789,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏أَخْبَرنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَنَتَ ‏ ‏فِي الصُّبْحِ وَفِي الْمَغْرِبِ ‏","","",""],[17790,17790,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ عُلَيَّةَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ عُتَيْبَةَ ‏ ‏اسْتَعْمَلَ ‏ ‏أَبَا عُبَيْدَةَ بْنَ عَبْدِ اللَّهِ ‏ ‏عَلَى الصَّلَاةِ أَيَّامَ ‏ ‏ابْنِ الْأَشْعَثِ ‏ ‏فَكَانَ إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَامَ قَدْرَ مَا أَقُولُ ‏ ‏أَوْ وَقَدْ قَالَ قَدْرَ قَوْلِهِ ‏ ‏اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدَهُ أَهْلَ الثَّنَاءِ وَالْمَجْدِ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا ‏ ‏الْجَدِّ ‏ ‏مِنْكَ ‏ ‏الْجَدُّ ‏ ‏قَالَ ‏ ‏الْحَكَمُ ‏ ‏فَحَدَّثْتُ ذَاكَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبِي لَيْلَى ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏الْبَرَاءُ بْنُ عَازِبٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏رُكُوعُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ وَسُجُودُهُ وَمَا بَيْنَ السَّجْدَتَيْنِ قَرِيبًا مِنْ السَّوَاءِ ‏","","",""],[17791,17791,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ ‏ ‏يَخْطُبُ ‏ ‏فَقَالَ حَدَّثَنَا ‏ ‏الْبَرَاءُ ‏ ‏فَكَانَ غَيْرَ كَذُوبٍ ‏ ‏أَنَّهُمْ كَانُوا ‏ ‏إِذَا صَلَّوْا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَامُوا قِيَامًا حَتَّى يَرَوْهُ سَاجِدًا ثُمَّ سَجَدُوا ‏","","",""],[17792,17792,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ قَالَ فَأَحْرَمْنَا بِالْحَجِّ فَلَمَّا قَدِمْنَا ‏ ‏مَكَّةَ ‏ ‏قَالَ ‏ ‏اجْعَلُوا حَجَّكُمْ عُمْرَةً قَالَ فَقَالَ النَّاسُ يَا رَسُولَ اللَّهِ قَدْ أَحْرَمْنَا بِالْحَجِّ فَكَيْفَ نَجْعَلُهَا عُمْرَةً قَالَ انْظُرُوا مَا آمُرُكُمْ بِهِ فَافْعَلُوا فَرَدُّوا عَلَيْهِ الْقَوْلَ فَغَضِبَ ثُمَّ انْطَلَقَ حَتَّى دَخَلَ عَلَى ‏ ‏عَائِشَةَ ‏ ‏غَضْبَانَ فَرَأَتْ الْغَضَبَ فِي وَجْهِهِ فَقَالَتْ مَنْ أَغْضَبَكَ أَغْضَبَهُ اللَّهُ قَالَ وَمَا لِي لَا أَغْضَبُ وَأَنَا آمُرُ بِالْأَمْرِ فَلَا أُتَّبَعُ ‏","","",""],[17793,17793,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ سُوَيْدِ بْنِ مُقَرِّنٍ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَيُّ عُرَى الْإِسْلَامِ أَوْسَطُ قَالُوا الصَّلَاةُ قَالَ حَسَنَةٌ وَمَا هِيَ بِهَا قَالُوا الزَّكَاةُ قَالَ حَسَنَةٌ وَمَا هِيَ بِهَا قَالُوا صِيَامُ رَمَضَانَ قَالَ حَسَنٌ وَمَا هُوَ بِهِ قَالُوا الْحَجُّ قَالَ حَسَنٌ وَمَا هُوَ بِهِ قَالُوا الْجِهَادُ قَالَ حَسَنٌ وَمَا هُوَ بِهِ قَالَ إِنَّ ‏ ‏أَوْسَطَ عُرَى الْإِيمَانِ أَنْ تُحِبَّ فِي اللَّهِ وَتُبْغِضَ فِي اللَّهِ ‏","","",""],[17794,17794,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏مُرَّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَهُودِيٍّ ‏ ‏مُحَمَّمٍ ‏ ‏مَجْلُودٍ فَدَعَاهُمْ فَقَالَ أَهَكَذَا تَجِدُونَ حَدَّ الزَّانِي فِي كِتَابِكُمْ فَقَالُوا نَعَمْ قَالَ فَدَعَا رَجُلًا مِنْ عُلَمَائِهِمْ فَقَالَ ‏ ‏أَنْشُدُكَ ‏ ‏بِاللَّهِ الَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى ‏ ‏مُوسَى ‏ ‏أَهَكَذَا تَجِدُونَ حَدَّ الزَّانِي فِي كِتَابِكُمْ فَقَالَ لَا وَاللَّهِ وَلَوْلَا أَنَّكَ ‏ ‏أَنْشَدْتَنِي ‏ ‏بِهَذَا لَمْ أُخْبِرْكَ نَجِدُ حَدَّ الزَّانِي فِي كِتَابِنَا ‏ ‏الرَّجْمَ ‏ ‏وَلَكِنَّهُ كَثُرَ فِي أَشْرَافِنَا فَكُنَّا إِذَا أَخَذْنَا الشَّرِيفَ تَرَكْنَاهُ وَإِذَا أَخَذْنَا الضَّعِيفَ أَقَمْنَا عَلَيْهِ الْحَدَّ فَقُلْنَا تَعَالَوْا حَتَّى نَجْعَلَ شَيْئًا نُقِيمُهُ عَلَى الشَّرِيفِ وَالْوَضِيعِ فَاجْتَمَعْنَا عَلَى ‏ ‏التَّحْمِيمِ ‏ ‏وَالْجَلْدِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنِّي أَوَّلُ مَنْ أَحْيَا أَمْرَكَ إِذْ أَمَاتُوهُ قَالَ فَأَمَرَ بِهِ ‏ ‏فَرُجِمَ ‏ ‏فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏يَا أَيُّهَا الرَّسُولُ لَا يَحْزُنْكَ الَّذِينَ يُسَارِعُونَ فِي الْكُفْرِ ‏ ‏إِلَى قَوْلِهِ ‏ ‏يَقُولُونَ إِنْ أُوتِيتُمْ هَذَا فَخُذُوهُ ‏} ‏يَقُولُونَ ائْتُوا ‏ ‏مُحَمَّدًا ‏ ‏فَإِنْ أَفْتَاكُمْ ‏ ‏بِالتَّحْمِيمِ ‏ ‏وَالْجَلْدِ فَخُذُوهُ وَإِنْ أَفْتَاكُمْ ‏ ‏بِالرَّجْمِ ‏ ‏فَاحْذَرُوا ‏ ‏إِلَى قَوْلِهِ ‏ { ‏وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمْ الْكَافِرُونَ ‏} ‏قَالَ فِي ‏ ‏الْيَهُودِ ‏ ‏إِلَى قَوْلِهِ ‏ { ‏وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمْ الظَّالِمُونَ ‏} { ‏وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمْ الْفَاسِقُونَ ‏} ‏قَالَ هِيَ فِي الْكُفَّارِ كُلُّهَا ‏","","",""],[17795,17795,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَسَّانَ بْنِ ثَابِتٍ ‏ ‏اهْجُ ‏ ‏الْمُشْرِكِينَ فَإِنَّ ‏ ‏جِبْرِيلَ ‏ ‏مَعَكَ ‏","","",""],[17796,17796,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏أَنَّهُ ‏ ‏صَلَّى خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِشَاءَ الْآخِرَةَ فَقَرَأَ ‏ ‏وَالتِّينِ وَالزَّيْتُونِ ‏","","",""],[17797,17797,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَغْرِبَ فَقَرَأَ ‏ ‏بِالتِّينِ وَالزَّيْتُونِ ‏","","",""],[17798,17798,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَوْلُهُ ‏ { ‏وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمْ الْكَافِرُونَ ‏} { ‏وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمْ الظَّالِمُونَ ‏} { ‏وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمْ الْفَاسِقُونَ ‏} ‏قَالَ هِيَ فِي الْكُفَّارِ كُلُّهَا ‏","","",""],[17799,17799,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَنَانُ بْنُ عَبْدِ اللَّهِ النَّهْمِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْسَجَةَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْشُوا السَّلَامَ تَسْلَمُوا ‏ ‏وَالْأَشَرَةُ ‏ ‏أَشَرُّ ‏","","",""],[17800,17800,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَنَانُ بْنُ عَبْدِ اللَّهِ النَّهْمِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْسَجَةَ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ ‏ ‏لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ أَوْ ‏ ‏مَنَحَ ‏ ‏مِنْحَةً ‏ ‏أَوْ هَدَى ‏ ‏زُقَاقًا ‏ ‏كَانَ كَمَنْ أَعْتَقَ رَقَبَةً ‏ ‏يَقُولُ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏كَانَ ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏قَلِيلَ الذِّكْرِ لِلنَّاسِ مَا سَمِعْتُهُ ذَكَرَ أَحَدًا غَيْرَ ‏ ‏قَنَانٍ ‏ ‏قَالَ قَالَ ‏ ‏لَنَا يَوْمًا قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ هَذَا مِنْ ‏ ‏بَابَتِكُمْ ‏","","",""]];
